INSERT INTO platform_private.learning_items (id, module_id, item_key, topic_key, syllabus_point, difficulty, pool, provenance, body)
VALUES
  ('c4dba1cf-e870-5f9a-89f1-9f4d75130dbf', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-exp-log-001', 'm2-exp-log', '2.2', 1, 'lesson', 'evo_authored', '{"stem_en":"Find the value of $\\log_2 8 + \\log_2 4$.","options":[{"id":"a","label":"$6$","explain_ru":"Неверно: значения логарифмов перемножили: $3 \\cdot 2 = 6$. При сложении логарифмов их значения складываются: $3 + 2$.","explain_ky":"Туура эмес: логарифмдердин маанилери көбөйтүлгөн: $3 \\cdot 2 = 6$. Логарифмдерди кошкондо алардын маанилери кошулат: $3 + 2$."},{"id":"b","label":"$5$","explain_ru":"Верно: $\\log_2 8 = 3$ и $\\log_2 4 = 2$, сумма $5$. То же даёт правило произведения: $\\log_2 32 = 5$.","explain_ky":"Туура: $\\log_2 8 = 3$ жана $\\log_2 4 = 2$, суммасы $5$. Көбөйтүндү эрежеси да ушуну берет: $\\log_2 32 = 5$."},{"id":"c","label":"$\\log_2 12$","explain_ru":"Неверно: сложили аргументы. Сумма логарифмов с одним основанием равна логарифму произведения $\\log_2 (8 \\cdot 4)$, а не суммы.","explain_ky":"Туура эмес: аргументтер кошулган. Негизи бирдей логарифмдердин суммасы суммага эмес, $\\log_2 (8 \\cdot 4)$ көбөйтүндүсүнүн логарифмине барабар."},{"id":"d","label":"$32$","explain_ru":"Неверно: $32 = 8 \\cdot 4$ это аргумент. Нужен сам логарифм: $\\log_2 32 = 5$.","explain_ky":"Туура эмес: $32 = 8 \\cdot 4$ бул аргумент. Логарифмдин өзү керек: $\\log_2 32 = 5$."}],"answer_index":1,"solution_ru":["$2^3 = 8$, значит $\\log_2 8 = 3$.","$2^2 = 4$, значит $\\log_2 4 = 2$.","$3 + 2 = 5$."],"solution_ky":["$2^3 = 8$, демек $\\log_2 8 = 3$.","$2^2 = 4$, демек $\\log_2 4 = 2$.","$3 + 2 = 5$."],"terms":[{"en":"logarithm","ru":"логарифм","ky":"логарифм"},{"en":"base","ru":"основание","ky":"негиз"}],"skill":"log-laws","est_seconds":45}'::JSONB),
  ('09146eb8-69ed-5420-8c40-f7af9e29e72e', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-exp-log-002', 'm2-exp-log', '2.2', 1, 'lesson', 'evo_authored', '{"stem_en":"Which of the following functions is decreasing on its entire domain?","options":[{"id":"a","label":"$y = 3^x$","explain_ru":"Неверно: основание $3 > 1$, такая показательная функция возрастает.","explain_ky":"Туура эмес: негизи $3 > 1$, мындай көрсөткүчтүү функция өсөт."},{"id":"b","label":"$y = \\log_5 x$","explain_ru":"Неверно: основание $5 > 1$, такой логарифм возрастает на всей области определения.","explain_ky":"Туура эмес: негизи $5 > 1$, мындай логарифм бүт аныкталуу областында өсөт."},{"id":"c","label":"$y = \\left(\\frac{1}{2}\\right)^{-x}$","explain_ru":"Неверно: основание $\\frac{1}{2}$ сбивает с толку, но $\\left(\\frac{1}{2}\\right)^{-x} = 2^x$, а эта функция возрастает.","explain_ky":"Туура эмес: $\\frac{1}{2}$ негизи адаштырат, бирок $\\left(\\frac{1}{2}\\right)^{-x} = 2^x$, ал эми бул функция өсөт."},{"id":"d","label":"$y = \\log_{1/2} x$","explain_ru":"Верно: основание $\\frac{1}{2}$ лежит между $0$ и $1$, поэтому логарифм убывает при всех $x > 0$.","explain_ky":"Туура: $\\frac{1}{2}$ негизи $0$ менен $1$ ортосунда жатат, ошондуктан логарифм бардык $x > 0$ үчүн кемийт."}],"answer_index":3,"solution_ru":["Функции $a^x$ и $\\log_a x$ убывают при $0 < a < 1$ и возрастают при $a > 1$.","Перепишем $\\left(\\frac{1}{2}\\right)^{-x}$ иначе: $\\left(\\frac{1}{2}\\right)^{-x} = 2^x$, основание $2 > 1$.","Убывает только $y = \\log_{1/2} x$."],"solution_ky":["$a^x$ жана $\\log_a x$ функциялары $0 < a < 1$ болгондо кемийт, $a > 1$ болгондо өсөт.","$\\left(\\frac{1}{2}\\right)^{-x}$ туюнтмасын кайра жазабыз: $\\left(\\frac{1}{2}\\right)^{-x} = 2^x$, негизи $2 > 1$.","Бир гана $y = \\log_{1/2} x$ кемийт."],"terms":[{"en":"decreasing function","ru":"убывающая функция","ky":"кемүүчү функция"},{"en":"domain","ru":"область определения","ky":"аныкталуу областы"}],"skill":"monotonic-base","est_seconds":45}'::JSONB),
  ('97c49fd2-9336-5a64-8b0d-76ba18956998', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-exp-log-003', 'm2-exp-log', '2.2', 1, 'lesson', 'evo_authored', '{"stem_en":"What is the domain of the function $f(x) = \\log_2 (x - 3)$?","options":[{"id":"a","label":"$(3, +\\infty)$","explain_ru":"Верно: аргумент логарифма должен быть положительным: $x - 3 > 0$, то есть $x > 3$.","explain_ky":"Туура: логарифмдин аргументи оң болушу керек: $x - 3 > 0$, башкача айтканда $x > 3$."},{"id":"b","label":"$[3, +\\infty)$","explain_ru":"Неверно: при $x = 3$ получаем $\\log_2 0$, а логарифм нуля не определён. Поэтому число $3$ в область не входит.","explain_ky":"Туура эмес: $x = 3$ болгондо $\\log_2 0$ чыгат, ал эми нөлдүн логарифми аныкталган эмес. Ошондуктан $3$ саны областка кирбейт."},{"id":"c","label":"$(0, +\\infty)$","explain_ru":"Неверно: это область определения $\\log_2 x$. Здесь под логарифмом стоит $x - 3$, и условие другое: $x - 3 > 0$.","explain_ky":"Туура эмес: бул $\\log_2 x$ функциясынын аныкталуу областы. Бул жерде логарифмдин астында $x - 3$ турат, шарт башка: $x - 3 > 0$."},{"id":"d","label":"$(-3, +\\infty)$","explain_ru":"Неверно: ошибка в знаке. Из $x - 3 > 0$ следует $x > 3$, а не $x > -3$.","explain_ky":"Туура эмес: белгиде ката. $x - 3 > 0$ шартынан $x > -3$ эмес, $x > 3$ келип чыгат."}],"answer_index":0,"solution_ru":["Логарифм определён только для положительного аргумента.","$x - 3 > 0 \\Rightarrow x > 3$.","Ответ: $(3, +\\infty)$."],"solution_ky":["Логарифм оң аргумент үчүн гана аныкталган.","$x - 3 > 0 \\Rightarrow x > 3$.","Жооп: $(3, +\\infty)$."],"terms":[{"en":"domain","ru":"область определения","ky":"аныкталуу областы"},{"en":"argument of a logarithm","ru":"аргумент логарифма","ky":"логарифмдин аргументи"}],"skill":"domain","est_seconds":45}'::JSONB),
  ('eb546204-e2e4-5f0c-80ac-f51c866e795b', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-exp-log-004', 'm2-exp-log', '2.2', 2, 'practice', 'evo_authored', '{"stem_en":"Solve the equation $4^x - 3 \\cdot 2^x - 4 = 0$.","options":[{"id":"a","label":"$x = 4$","explain_ru":"Неверно: $4$ это значение $t = 2^x$, а не $x$. Из $2^x = 4$ получаем $x = 2$.","explain_ky":"Туура эмес: $4$ бул $x$ эмес, $t = 2^x$ мааниси. $2^x = 4$ теңдемесинен $x = 2$ чыгат."},{"id":"b","label":"$x = 2$ or $x = -1$","explain_ru":"Неверно: корень $t = -1$ надо отбросить, потому что $2^x > 0$ при любом $x$. К тому же $-1$ это значение $t$, а не $x$.","explain_ky":"Туура эмес: $t = -1$ тамырын таштоо керек, анткени каалаган $x$ үчүн $2^x > 0$. Мындан тышкары $-1$ бул $x$ эмес, $t$ мааниси."},{"id":"c","label":"$x = 2$","explain_ru":"Верно: замена $t = 2^x > 0$ даёт $t^2 - 3t - 4 = 0$ с корнями $4$ и $-1$. Подходит только $t = 4$, отсюда $x = 2$.","explain_ky":"Туура: $t = 2^x > 0$ алмаштыруусу $t^2 - 3t - 4 = 0$ теңдемесин берет, тамырлары $4$ жана $-1$. $t = 4$ гана туура келет, демек $x = 2$."},{"id":"d","label":"The equation has no real solution.","explain_ru":"Неверно: отрицательный корень $t = -1$ отбрасывается, но остаётся $t = 4$, то есть $x = 2$.","explain_ky":"Туура эмес: терс $t = -1$ тамыры ташталат, бирок $t = 4$ калат, башкача айтканда $x = 2$."}],"answer_index":2,"solution_ru":["Заметим, что $4^x = (2^x)^2$. Пусть $t = 2^x$, тогда $t > 0$.","$t^2 - 3t - 4 = 0 \\Rightarrow (t - 4)(t + 1) = 0$, то есть $t = 4$ или $t = -1$.","$t = -1$ не подходит, так как $t > 0$.","$2^x = 4 \\Rightarrow x = 2$."],"solution_ky":["$4^x = (2^x)^2$ экенин байкайбыз. $t = 2^x$ деп белгилейбиз, анда $t > 0$.","$t^2 - 3t - 4 = 0 \\Rightarrow (t - 4)(t + 1) = 0$, башкача айтканда $t = 4$ же $t = -1$.","$t = -1$ туура келбейт, анткени $t > 0$.","$2^x = 4 \\Rightarrow x = 2$."],"terms":[{"en":"substitution","ru":"замена переменной","ky":"өзгөрмөнү алмаштыруу"},{"en":"real solution","ru":"действительное решение","ky":"чыныгы чыгарылыш"}],"skill":"exp-equation-substitution","est_seconds":75}'::JSONB),
  ('59afaff6-4cf6-5295-899e-fbf6692ce98b', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-exp-log-005', 'm2-exp-log', '2.2', 2, 'lesson', 'evo_authored', '{"stem_en":"Let $\\log_a 2 = m$ and $\\log_a 3 = n$. Express $\\log_a 12$ in terms of $m$ and $n$.","options":[{"id":"a","label":"$2m + n$","explain_ru":"Верно: $12 = 2^2 \\cdot 3$, поэтому $\\log_a 12 = 2\\log_a 2 + \\log_a 3 = 2m + n$.","explain_ky":"Туура: $12 = 2^2 \\cdot 3$, ошондуктан $\\log_a 12 = 2\\log_a 2 + \\log_a 3 = 2m + n$."},{"id":"b","label":"$m^2 + n$","explain_ru":"Неверно: логарифм квадрата не равен квадрату логарифма. Показатель выносится множителем: $\\log_a 2^2 = 2m$, а не $m^2$.","explain_ky":"Туура эмес: квадраттын логарифми логарифмдин квадратына барабар эмес. Даража көрсөткүчү көбөйтүүчү болуп алдыга чыгат: $\\log_a 2^2 = 2m$, $m^2$ эмес."},{"id":"c","label":"$2mn$","explain_ru":"Неверно: логарифм произведения равен сумме логарифмов, а не их произведению.","explain_ky":"Туура эмес: көбөйтүндүнүн логарифми логарифмдердин көбөйтүндүсүнө эмес, суммасына барабар."},{"id":"d","label":"$2(m + n)$","explain_ru":"Неверно: $2(m + n) = 2\\log_a 6 = \\log_a 36$. Множитель $2$ из записи $12 = 2 \\cdot 6$ спутали с показателем степени.","explain_ky":"Туура эмес: $2(m + n) = 2\\log_a 6 = \\log_a 36$. $12 = 2 \\cdot 6$ жазуусундагы $2$ көбөйтүүчүсү даража көрсөткүчү менен чаташтырылган."}],"answer_index":0,"solution_ru":["Разложим $12 = 2^2 \\cdot 3$.","$\\log_a 12 = \\log_a 2^2 + \\log_a 3 = 2\\log_a 2 + \\log_a 3$.","Ответ: $2m + n$."],"solution_ky":["$12 = 2^2 \\cdot 3$ деп ажыратабыз.","$\\log_a 12 = \\log_a 2^2 + \\log_a 3 = 2\\log_a 2 + \\log_a 3$.","Жооп: $2m + n$."],"terms":[{"en":"product rule for logarithms","ru":"логарифм произведения","ky":"көбөйтүндүнүн логарифми"},{"en":"power rule for logarithms","ru":"логарифм степени","ky":"даражанын логарифми"}],"skill":"log-laws","est_seconds":75}'::JSONB),
  ('3fc2ae12-468b-503b-8ad8-4909d4d6b1a4', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-exp-log-006', 'm2-exp-log', '2.2', 2, 'mock', 'evo_authored', '{"stem_en":"The figure shows the graph of $y = a^x + b$ ($a > 0$, $a \\ne 1$) together with its horizontal asymptote. Find $a + b$.","options":[{"id":"a","label":"$2$","explain_ru":"Неверно: это значение $a$. Нужна сумма $a + b$, а $b = -1$, потому что асимптота $y = -1$.","explain_ky":"Туура эмес: бул $a$ санынын мааниси. $a + b$ суммасы керек, ал эми $b = -1$, анткени асимптота $y = -1$."},{"id":"b","label":"$1$","explain_ru":"Верно: асимптота $y = -1$ даёт $b = -1$. Из точки $(1, 1)$: $a - 1 = 1$, значит $a = 2$ и $a + b = 1$.","explain_ky":"Туура: $y = -1$ асимптотасы $b = -1$ берет. $(1, 1)$ чекитинен: $a - 1 = 1$, демек $a = 2$ жана $a + b = 1$."},{"id":"c","label":"$3$","explain_ru":"Неверно: ошибка в знаке асимптоты. График приближается к прямой $y = -1$, значит $b = -1$, а не $1$.","explain_ky":"Туура эмес: асимптотанын белгисинде ката. График $y = -1$ түз сызыгына жакындайт, демек $b = 1$ эмес, $b = -1$."},{"id":"d","label":"$\\sqrt{3} - 1$","explain_ru":"Неверно: по точке $(2, 3)$ записали $a^2 = 3$ и забыли про $b$. С учётом $b = -1$ будет $a^2 - 1 = 3$, то есть $a = 2$.","explain_ky":"Туура эмес: $(2, 3)$ чекити боюнча $a^2 = 3$ деп жазылып, $b$ унутулган. $b = -1$ эске алынса, $a^2 - 1 = 3$, башкача айтканда $a = 2$."}],"answer_index":1,"solution_ru":["Если $x \\to -\\infty$, слагаемое $a^x$ стремится к нулю (здесь $a > 1$, график растёт), поэтому асимптота $y = b$. По рисунку $b = -1$.","Точка $(1, 1)$: $a^1 + b = 1 \\Rightarrow a = 2$.","Проверка точкой $(2, 3)$: $2^2 - 1 = 3$.","$a + b = 2 + (-1) = 1$."],"solution_ky":["$x \\to -\\infty$ болгондо $a^x$ кошулуучусу нөлгө умтулат (бул жерде $a > 1$, график өсөт), ошондуктан асимптота $y = b$. Сүрөт боюнча $b = -1$.","$(1, 1)$ чекити: $a^1 + b = 1 \\Rightarrow a = 2$.","$(2, 3)$ чекити менен текшерүү: $2^2 - 1 = 3$.","$a + b = 2 + (-1) = 1$."],"terms":[{"en":"horizontal asymptote","ru":"горизонтальная асимптота","ky":"горизонталдык асимптота"},{"en":"the graph passes through a point","ru":"график проходит через точку","ky":"график чекит аркылуу өтөт"}],"skill":"graph-reading","est_seconds":75,"figure_key":"item-exp-graph"}'::JSONB),
  ('42ceb05b-f269-5809-8644-ab171759f77e', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-exp-log-007', 'm2-exp-log', '2.2', 2, 'diagnostic', 'evo_authored', '{"stem_en":"Let $a = \\log_2 3$, $b = \\log_3 2$ and $c = \\log_{1/2} 3$. Which of the following is correct?","options":[{"id":"a","label":"$b > a > c$","explain_ru":"Неверно: $a = \\log_2 3 > 1$, потому что $3 > 2$, а $b = \\log_3 2 < 1$, потому что $2 < 3$. Значит $a > b$.","explain_ky":"Туура эмес: $3 > 2$ болгондуктан $a = \\log_2 3 > 1$, ал эми $2 < 3$ болгондуктан $b = \\log_3 2 < 1$. Демек $a > b$."},{"id":"b","label":"$a > c > b$","explain_ru":"Неверно: $c$ отрицательно, так как основание $\\frac{1}{2} < 1$, а аргумент $3 > 1$. А $b > 0$, поэтому $b > c$.","explain_ky":"Туура эмес: $c$ терс, анткени негизи $\\frac{1}{2} < 1$, аргументи $3 > 1$. Ал эми $b > 0$, ошондуктан $b > c$."},{"id":"c","label":"$c > a > b$","explain_ru":"Неверно: $c = \\log_{1/2} 3 = -\\log_2 3 < 0$, это самое маленькое из трёх чисел.","explain_ky":"Туура эмес: $c = \\log_{1/2} 3 = -\\log_2 3 < 0$, бул үч сандын эң кичинеси."},{"id":"d","label":"$a > b > c$","explain_ru":"Верно: $a > 1$, $0 < b < 1$, $c < 0$. Сравнение с $0$ и $1$ решает задачу без калькулятора.","explain_ky":"Туура: $a > 1$, $0 < b < 1$, $c < 0$. $0$ жана $1$ менен салыштыруу маселени калькуляторсуз чечет."}],"answer_index":3,"solution_ru":["$\\log_2 3 > \\log_2 2 = 1$, значит $a > 1$.","$0 = \\log_3 1 < \\log_3 2 < \\log_3 3 = 1$, значит $0 < b < 1$.","Основание $\\frac{1}{2} < 1$, функция убывает: $\\log_{1/2} 3 < \\log_{1/2} 1 = 0$, значит $c < 0$.","Итог: $a > b > c$."],"solution_ky":["$\\log_2 3 > \\log_2 2 = 1$, демек $a > 1$.","$0 = \\log_3 1 < \\log_3 2 < \\log_3 3 = 1$, демек $0 < b < 1$.","Негизи $\\frac{1}{2} < 1$, функция кемийт: $\\log_{1/2} 3 < \\log_{1/2} 1 = 0$, демек $c < 0$.","Жыйынтык: $a > b > c$."],"terms":[{"en":"compare","ru":"сравнить","ky":"салыштыруу"},{"en":"logarithm","ru":"логарифм","ky":"логарифм"}],"skill":"compare-without-calculator","est_seconds":75}'::JSONB),
  ('9ad84c18-2034-53da-8bf5-519babcfb0f8', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-exp-log-008', 'm2-exp-log', '2.2', 3, 'mock', 'evo_authored', '{"stem_en":"Solve the inequality $\\log_{1/2} (x - 1) > -2$.","options":[{"id":"a","label":"$x > 5$","explain_ru":"Неверно: основание $\\frac{1}{2} < 1$, функция убывает, поэтому при переходе к аргументам знак неравенства меняется: $x - 1 < 4$.","explain_ky":"Туура эмес: негизи $\\frac{1}{2} < 1$, функция кемийт, ошондуктан аргументтерге өткөндө барабарсыздыктын белгиси өзгөрөт: $x - 1 < 4$."},{"id":"b","label":"$x < 5$","explain_ru":"Неверно: забыта область определения. Аргумент должен быть положительным: $x - 1 > 0$, то есть $x > 1$.","explain_ky":"Туура эмес: аныкталуу областы унутулган. Аргумент оң болушу керек: $x - 1 > 0$, башкача айтканда $x > 1$."},{"id":"c","label":"$1 < x < 5$","explain_ru":"Верно: $-2 = \\log_{1/2} 4$. Функция убывает, поэтому $x - 1 < 4$, а вместе с условием $x - 1 > 0$ получаем $1 < x < 5$.","explain_ky":"Туура: $-2 = \\log_{1/2} 4$. Функция кемийт, ошондуктан $x - 1 < 4$, ал эми $x - 1 > 0$ шарты менен бирге $1 < x < 5$ чыгат."},{"id":"d","label":"$1 < x < \\frac{5}{4}$","explain_ru":"Неверно: ошибка в степени. $\\left(\\frac{1}{2}\\right)^{-2} = 4$, а не $\\frac{1}{4}$.","explain_ky":"Туура эмес: даражада ката. $\\left(\\frac{1}{2}\\right)^{-2} = 4$, $\\frac{1}{4}$ эмес."}],"answer_index":2,"solution_ru":["Область определения: $x - 1 > 0$, то есть $x > 1$.","Запишем правую часть как логарифм: $-2 = \\log_{1/2}\\left(\\left(\\frac{1}{2}\\right)^{-2}\\right) = \\log_{1/2} 4$.","Основание меньше $1$, функция убывает: $\\log_{1/2} (x - 1) > \\log_{1/2} 4 \\Leftrightarrow x - 1 < 4$.","Вместе с областью определения: $1 < x < 5$."],"solution_ky":["Аныкталуу областы: $x - 1 > 0$, башкача айтканда $x > 1$.","Оң жагын логарифм түрүндө жазабыз: $-2 = \\log_{1/2}\\left(\\left(\\frac{1}{2}\\right)^{-2}\\right) = \\log_{1/2} 4$.","Негизи бирден кичине, функция кемийт: $\\log_{1/2} (x - 1) > \\log_{1/2} 4 \\Leftrightarrow x - 1 < 4$.","Аныкталуу областы менен бирге: $1 < x < 5$."],"terms":[{"en":"inequality","ru":"неравенство","ky":"барабарсыздык"},{"en":"decreasing function","ru":"убывающая функция","ky":"кемүүчү функция"}],"skill":"log-inequality","est_seconds":105}'::JSONB),
  ('33aac6cd-6eb8-5ed2-85da-67c38d503841', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-exp-log-009', 'm2-exp-log', '2.2', 3, 'practice', 'evo_authored', '{"stem_en":"Find the range of the function $f(x) = \\log_2 (x^2 - 4x + 5)$ for $x \\in [0, 3]$.","options":[{"id":"a","label":"$[0, \\log_2 5]$","explain_ru":"Верно: $x^2 - 4x + 5 = (x - 2)^2 + 1$ на отрезке $[0, 3]$ принимает значения от $1$ (при $x = 2$) до $5$ (при $x = 0$). Логарифм по основанию $2$ возрастает, поэтому $f$ меняется от $0$ до $\\log_2 5$.","explain_ky":"Туура: $x^2 - 4x + 5 = (x - 2)^2 + 1$ туюнтмасынын $[0, 3]$ кесиндисиндеги эң кичине мааниси $1$ ($x = 2$ болгондо), эң чоң мааниси $5$ ($x = 0$ болгондо). Негизи $2$ болгон логарифм өсөт, ошондуктан $f$ маанилери $0$ жана $\\log_2 5$ ортосунда болот."},{"id":"b","label":"$[1, \\log_2 5]$","explain_ru":"Неверно: проверили только концы отрезка ($f(3) = 1$, $f(0) = \\log_2 5$) и пропустили вершину $x = 2$, где $f(2) = \\log_2 1 = 0$.","explain_ky":"Туура эмес: кесиндинин учтары гана текшерилген ($f(3) = 1$, $f(0) = \\log_2 5$), ал эми $x = 2$ чокусу калып калган, анда $f(2) = \\log_2 1 = 0$."},{"id":"c","label":"$[0, 1]$","explain_ru":"Неверно: наибольшее значение искали только на правом конце, $f(3) = \\log_2 2 = 1$. На левом конце больше: $f(0) = \\log_2 5 > 1$.","explain_ky":"Туура эмес: эң чоң маани оң учта гана изделген, $f(3) = \\log_2 2 = 1$. Сол учта чоңураак: $f(0) = \\log_2 5 > 1$."},{"id":"d","label":"$[1, 5]$","explain_ru":"Неверно: это значения выражения под логарифмом. Нужны значения самой функции: от $\\log_2 1 = 0$ до $\\log_2 5$.","explain_ky":"Туура эмес: бул логарифмдин астындагы туюнтманын маанилери. Функциянын өзүнүн маанилери керек: $\\log_2 1 = 0$ жана $\\log_2 5$ ортосунда."}],"answer_index":0,"solution_ru":["Выделим полный квадрат: $x^2 - 4x + 5 = (x - 2)^2 + 1$.","На $[0, 3]$ выражение наименьшее при $x = 2$ (равно $1$), а на концах равно $5$ при $x = 0$ и $2$ при $x = 3$. Значит, оно принимает все значения из $[1, 5]$.","$\\log_2 t$ возрастает, поэтому $f$ принимает значения от $\\log_2 1 = 0$ до $\\log_2 5$.","Ответ: $[0, \\log_2 5]$."],"solution_ky":["Толук квадратты бөлүп чыгарабыз: $x^2 - 4x + 5 = (x - 2)^2 + 1$.","$[0, 3]$ кесиндисинде туюнтма $x = 2$ болгондо эң кичине ($1$ барабар), ал эми учтарында $x = 0$ болгондо $5$, $x = 3$ болгондо $2$. Демек, ал $[1, 5]$ аралыгындагы бардык маанилерди алат.","$\\log_2 t$ өсөт, ошондуктан $f$ маанилери $\\log_2 1 = 0$ жана $\\log_2 5$ ортосунда болот.","Жооп: $[0, \\log_2 5]$."],"terms":[{"en":"range","ru":"множество значений","ky":"маанилер областы"},{"en":"complete the square","ru":"выделить полный квадрат","ky":"толук квадратты бөлүп чыгаруу"}],"skill":"range-on-interval","est_seconds":105}'::JSONB),
  ('9de0f680-2f4c-5c23-83d2-133044236f9b', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-exp-log-010', 'm2-exp-log', '2.2', 3, 'practice', 'evo_authored', '{"stem_en":"If $3^a = 5^b = 15$, find the value of $\\frac{1}{a} + \\frac{1}{b}$.","options":[{"id":"a","label":"$\\frac{8}{15}$","explain_ru":"Неверно: из $3^a = 15$ получили $a = 5$ делением, а из $5^b = 15$ получили $b = 3$. Показатель находят логарифмом: $a = \\log_3 15$.","explain_ky":"Туура эмес: $3^a = 15$ теңдемесинен бөлүү менен $a = 5$, ал эми $5^b = 15$ теңдемесинен $b = 3$ алынган. Даража көрсөткүчү логарифм менен табылат: $a = \\log_3 15$."},{"id":"b","label":"$1$","explain_ru":"Верно: $a = \\log_3 15$ и $b = \\log_5 15$, поэтому $\\frac{1}{a} = \\log_{15} 3$, $\\frac{1}{b} = \\log_{15} 5$, сумма $\\log_{15} 15 = 1$.","explain_ky":"Туура: $a = \\log_3 15$ жана $b = \\log_5 15$, ошондуктан $\\frac{1}{a} = \\log_{15} 3$, $\\frac{1}{b} = \\log_{15} 5$, суммасы $\\log_{15} 15 = 1$."},{"id":"c","label":"$\\log_{15} 8$","explain_ru":"Неверно: сложили аргументы $3 + 5$. Сумма логарифмов равна логарифму произведения: $\\log_{15} (3 \\cdot 5)$.","explain_ky":"Туура эмес: $3 + 5$ аргументтери кошулган. Логарифмдердин суммасы көбөйтүндүнүн логарифмине барабар: $\\log_{15} (3 \\cdot 5)$."},{"id":"d","label":"$15$","explain_ru":"Неверно: $15 = 3 \\cdot 5$ это аргумент. Нужен логарифм: $\\log_{15} 15 = 1$.","explain_ky":"Туура эмес: $15 = 3 \\cdot 5$ бул аргумент. Логарифм керек: $\\log_{15} 15 = 1$."}],"answer_index":1,"solution_ru":["По определению логарифма: $a = \\log_3 15$, $b = \\log_5 15$.","Формула $\\frac{1}{\\log_x y} = \\log_y x$ даёт $\\frac{1}{a} = \\log_{15} 3$ и $\\frac{1}{b} = \\log_{15} 5$.","$\\log_{15} 3 + \\log_{15} 5 = \\log_{15} 15 = 1$."],"solution_ky":["Логарифмдин аныктамасы боюнча: $a = \\log_3 15$, $b = \\log_5 15$.","$\\frac{1}{\\log_x y} = \\log_y x$ формуласы $\\frac{1}{a} = \\log_{15} 3$ жана $\\frac{1}{b} = \\log_{15} 5$ берет.","$\\log_{15} 3 + \\log_{15} 5 = \\log_{15} 15 = 1$."],"terms":[{"en":"change of base formula","ru":"формула перехода к новому основанию","ky":"жаңы негизге өтүү формуласы"},{"en":"definition of a logarithm","ru":"определение логарифма","ky":"логарифмдин аныктамасы"}],"skill":"log-definition","est_seconds":105}'::JSONB),
  ('7ffa1c9d-5669-58af-833b-1066d1c4b23d', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-derivative-001', 'm2-derivative', '2.4', 1, 'lesson', 'evo_authored', '{"stem_en":"Let $f(x) = x^3 - 2x$. Find $f''(1)$.","options":[{"id":"a","label":"$-1$","explain_ru":"Неверно: это значение самой функции: $f(1) = 1 - 2 = -1$. Нужна производная в точке.","explain_ky":"Туура эмес: бул функциянын өзүнүн мааниси: $f(1) = 1 - 2 = -1$. Чекиттеги туунду керек."},{"id":"b","label":"$3$","explain_ru":"Неверно: потеряна производная слагаемого $-2x$, она равна $-2$.","explain_ky":"Туура эмес: $-2x$ кошулуучусунун туундусу жоголгон, ал $-2$ болот."},{"id":"c","label":"$1$","explain_ru":"Верно: $f''(x) = 3x^2 - 2$, поэтому $f''(1) = 3 - 2 = 1$.","explain_ky":"Туура: $f''(x) = 3x^2 - 2$, ошондуктан $f''(1) = 3 - 2 = 1$."},{"id":"d","label":"$5$","explain_ru":"Неверно: ошибка в знаке. Производная $-2x$ равна $-2$, а не $+2$.","explain_ky":"Туура эмес: белгиде ката. $-2x$ туундусу $+2$ эмес, $-2$."}],"answer_index":2,"solution_ru":["$(x^n)'' = nx^{n-1}$, поэтому $(x^3)'' = 3x^2$ и $(2x)'' = 2$.","$f''(x) = 3x^2 - 2$.","$f''(1) = 3 \\cdot 1 - 2 = 1$."],"solution_ky":["$(x^n)'' = nx^{n-1}$, ошондуктан $(x^3)'' = 3x^2$ жана $(2x)'' = 2$.","$f''(x) = 3x^2 - 2$.","$f''(1) = 3 \\cdot 1 - 2 = 1$."],"terms":[{"en":"derivative","ru":"производная","ky":"туунду"},{"en":"power rule","ru":"производная степени","ky":"даражанын туундусу"}],"skill":"derivative-rules","est_seconds":45}'::JSONB),
  ('84750178-5e93-598e-8e89-2db519420da9', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-derivative-002', 'm2-derivative', '2.4', 1, 'lesson', 'evo_authored', '{"stem_en":"What is the slope of the tangent line to the curve $y = x^2$ at the point $(3, 9)$?","options":[{"id":"a","label":"$6$","explain_ru":"Верно: угловой коэффициент касательной равен значению производной: $y'' = 2x$, при $x = 3$ получаем $6$.","explain_ky":"Туура: жаныманын бурчтук коэффициенти туундунун маанисине барабар: $y'' = 2x$, $x = 3$ болгондо $6$ чыгат."},{"id":"b","label":"$9$","explain_ru":"Неверно: $9$ это ордината точки касания, а не наклон.","explain_ky":"Туура эмес: $9$ бул жантаюу эмес, жануу чекитинин ординатасы."},{"id":"c","label":"$3$","explain_ru":"Неверно: $3$ это абсцисса точки. Наклон даёт производная $2x$ в этой точке.","explain_ky":"Туура эмес: $3$ бул чекиттин абсциссасы. Жантаюуну ушул чекиттеги $2x$ туундусу берет."},{"id":"d","label":"$2$","explain_ru":"Неверно: $2$ это коэффициент в формуле $y'' = 2x$. В неё ещё нужно подставить $x = 3$.","explain_ky":"Туура эмес: $2$ бул $y'' = 2x$ формуласындагы коэффициент. Ага дагы $x = 3$ коюу керек."}],"answer_index":0,"solution_ru":["Наклон касательной в точке $x_0$ равен $f''(x_0)$.","$y'' = 2x$, поэтому $y''(3) = 6$."],"solution_ky":["$x_0$ чекитиндеги жаныманын жантаюусу $f''(x_0)$ барабар.","$y'' = 2x$, ошондуктан $y''(3) = 6$."],"terms":[{"en":"tangent line","ru":"касательная","ky":"жаныма"},{"en":"slope","ru":"угловой коэффициент","ky":"бурчтук коэффициент"}],"skill":"tangent-slope","est_seconds":45}'::JSONB),
  ('6d06f870-6d9d-538b-895e-d955352e501c', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-derivative-003', 'm2-derivative', '2.4', 1, 'lesson', 'evo_authored', '{"stem_en":"On which interval is the function $f(x) = x^2 - 4x + 1$ decreasing?","options":[{"id":"a","label":"$(2, +\\infty)$","explain_ru":"Неверно: на этом промежутке $f''(x) = 2x - 4 > 0$, функция возрастает.","explain_ky":"Туура эмес: бул аралыкта $f''(x) = 2x - 4 > 0$, функция өсөт."},{"id":"b","label":"$(-\\infty, -2)$","explain_ru":"Неверно: ошибка в знаке. Из $2x - 4 < 0$ следует $x < 2$, а не $x < -2$.","explain_ky":"Туура эмес: белгиде ката. $2x - 4 < 0$ шартынан $x < -2$ эмес, $x < 2$ келип чыгат."},{"id":"c","label":"$(-\\infty, 4)$","explain_ru":"Неверно: границу нашли как $-b = 4$ вместо $-\\frac{b}{2a} = 2$. Проверьте точку $x = 3$: $f''(3) = 2 > 0$.","explain_ky":"Туура эмес: чек ара $-\\frac{b}{2a} = 2$ ордуна $-b = 4$ деп табылган. $x = 3$ чекитин текшериңиз: $f''(3) = 2 > 0$."},{"id":"d","label":"$(-\\infty, 2)$","explain_ru":"Верно: $f''(x) = 2x - 4 < 0$ при $x < 2$, там функция убывает.","explain_ky":"Туура: $x < 2$ болгондо $f''(x) = 2x - 4 < 0$, ал жерде функция кемийт."}],"answer_index":3,"solution_ru":["$f''(x) = 2x - 4$.","Функция убывает там, где $f''(x) < 0$: $2x - 4 < 0 \\Rightarrow x < 2$.","Ответ: $(-\\infty, 2)$."],"solution_ky":["$f''(x) = 2x - 4$.","Функция $f''(x) < 0$ болгон жерде кемийт: $2x - 4 < 0 \\Rightarrow x < 2$.","Жооп: $(-\\infty, 2)$."],"terms":[{"en":"decreasing on an interval","ru":"убывает на промежутке","ky":"аралыкта кемийт"},{"en":"derivative","ru":"производная","ky":"туунду"}],"skill":"monotonic-intervals","est_seconds":45}'::JSONB),
  ('03cfcec2-b837-532b-8545-4a0d48b8fb5d', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-derivative-004', 'm2-derivative', '2.4', 2, 'lesson', 'evo_authored', '{"stem_en":"Find the equation of the tangent line to the curve $y = x^3$ at $x = 1$.","options":[{"id":"a","label":"$y = 3x$","explain_ru":"Неверно: наклон $3$ найден верно, но прямая должна проходить через точку касания $(1, 1)$. Прямая $y = 3x$ проходит через $(1, 3)$.","explain_ky":"Туура эмес: $3$ жантаюусу туура табылган, бирок түз сызык $(1, 1)$ жануу чекити аркылуу өтүшү керек. $y = 3x$ түз сызыгы $(1, 3)$ аркылуу өтөт."},{"id":"b","label":"$y = 3x - 2$","explain_ru":"Верно: точка касания $(1, 1)$, наклон $y''(1) = 3$. По формуле $y - 1 = 3(x - 1)$ получаем $y = 3x - 2$.","explain_ky":"Туура: жануу чекити $(1, 1)$, жантаюу $y''(1) = 3$. $y - 1 = 3(x - 1)$ формуласы боюнча $y = 3x - 2$ чыгат."},{"id":"c","label":"$y = x$","explain_ru":"Неверно: в качестве наклона взяли значение функции $y(1) = 1$. Наклон равен производной: $y''(1) = 3$.","explain_ky":"Туура эмес: жантаюу катары функциянын мааниси $y(1) = 1$ алынган. Жантаюу туундуга барабар: $y''(1) = 3$."},{"id":"d","label":"$y = 3x + 2$","explain_ru":"Неверно: ошибка при раскрытии скобок. $y - 1 = 3x - 3$, поэтому $y = 3x - 2$.","explain_ky":"Туура эмес: кашааны ачууда ката. $y - 1 = 3x - 3$, ошондуктан $y = 3x - 2$."}],"answer_index":1,"solution_ru":["Точка касания: $y(1) = 1$, то есть $(1, 1)$.","Наклон: $y'' = 3x^2$, $y''(1) = 3$.","$y - 1 = 3(x - 1) \\Rightarrow y = 3x - 2$."],"solution_ky":["Жануу чекити: $y(1) = 1$, башкача айтканда $(1, 1)$.","Жантаюу: $y'' = 3x^2$, $y''(1) = 3$.","$y - 1 = 3(x - 1) \\Rightarrow y = 3x - 2$."],"terms":[{"en":"point of tangency","ru":"точка касания","ky":"жануу чекити"},{"en":"equation of a line","ru":"уравнение прямой","ky":"түз сызыктын теңдемеси"}],"skill":"tangent-equation","est_seconds":75}'::JSONB),
  ('67c94107-30dc-580f-8251-27ebdcd63fed', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-derivative-005', 'm2-derivative', '2.4', 2, 'mock', 'evo_authored', '{"stem_en":"The figure shows the graph of the derivative $y = f''(x)$ of a function $f(x)$. At which value of $x$ does $f(x)$ have a local maximum?","options":[{"id":"a","label":"$x = 2$","explain_ru":"Неверно: при $x = 2$ производная меняет знак с минуса на плюс. Это точка локального минимума.","explain_ky":"Туура эмес: $x = 2$ болгондо туунду белгисин минустан плюска өзгөртөт. Бул локалдык минимум чекити."},{"id":"b","label":"$x = \\frac{1}{2}$","explain_ru":"Неверно: здесь самая нижняя точка графика производной, но $f''\\left(\\frac{1}{2}\\right) \\ne 0$. Экстремум $f$ ищут там, где $f''$ равна нулю и меняет знак.","explain_ky":"Туура эмес: бул жерде туунду графигинин эң төмөнкү чекити, бирок $f''\\left(\\frac{1}{2}\\right) \\ne 0$. $f$ экстремуму $f''$ нөлгө барабар болуп, белгисин өзгөрткөн жерден изделет."},{"id":"c","label":"$x = -1$","explain_ru":"Верно: при $x = -1$ производная равна нулю и меняет знак с плюса на минус. Функция сначала растёт, потом убывает: это локальный максимум.","explain_ky":"Туура: $x = -1$ болгондо туунду нөлгө барабар жана белгисин плюстан минуска өзгөртөт. Функция адегенде өсөт, анан кемийт: бул локалдык максимум."},{"id":"d","label":"$f(x)$ has no local maximum.","explain_ru":"Неверно: на рисунке график $f''$, а не $f$. Парабола $f''$ открыта вверх, но из этого не следует, что у $f$ нет максимума.","explain_ky":"Туура эмес: сүрөттө $f$ эмес, $f''$ графиги. $f''$ параболасынын тармактары өйдө карайт, бирок андан $f$ функциясынын максимуму жок деген жыйынтык чыкпайт."}],"answer_index":2,"solution_ru":["По графику $f''(x) = 0$ при $x = -1$ и $x = 2$.","Левее $-1$ график выше оси, $f'' > 0$, и $f$ растёт. Между $-1$ и $2$ ниже оси, $f'' < 0$, и $f$ убывает. Правее $2$ снова $f'' > 0$.","Знак меняется с плюса на минус в точке $x = -1$: там локальный максимум."],"solution_ky":["График боюнча $x = -1$ жана $x = 2$ болгондо $f''(x) = 0$.","$-1$ден солдо график октон жогору, $f'' > 0$, $f$ өсөт. $-1$ менен $2$ ортосунда октон төмөн, $f'' < 0$, $f$ кемийт. $2$ден оңдо кайра $f'' > 0$.","Белги $x = -1$ чекитинде плюстан минуска өзгөрөт: ал жерде локалдык максимум."],"terms":[{"en":"local maximum","ru":"локальный максимум","ky":"локалдык максимум"},{"en":"sign change","ru":"смена знака","ky":"белгинин өзгөрүшү"}],"skill":"derivative-graph","est_seconds":75,"figure_key":"item-derivative-graph"}'::JSONB),
  ('fd97aa28-b16c-510c-857d-f649a0ccc7fe', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-derivative-006', 'm2-derivative', '2.4', 2, 'practice', 'evo_authored', '{"stem_en":"Find the local minimum value of the function $f(x) = x^3 - 3x$.","options":[{"id":"a","label":"$-2$","explain_ru":"Верно: $f''(x) = 3x^2 - 3 = 0$ при $x = \\pm 1$. При $x = 1$ знак меняется с минуса на плюс, минимум $f(1) = 1 - 3 = -2$.","explain_ky":"Туура: $x = \\pm 1$ болгондо $f''(x) = 3x^2 - 3 = 0$. $x = 1$ болгондо белги минустан плюска өзгөрөт, минимум $f(1) = 1 - 3 = -2$."},{"id":"b","label":"$2$","explain_ru":"Неверно: $2 = f(-1)$ это локальный максимум: при $x = -1$ производная меняет знак с плюса на минус.","explain_ky":"Туура эмес: $2 = f(-1)$ бул локалдык максимум: $x = -1$ болгондо туунду белгисин плюстан минуска өзгөртөт."},{"id":"c","label":"$1$","explain_ru":"Неверно: $1$ это точка минимума $x$, а спрашивают значение функции $f(1)$.","explain_ky":"Туура эмес: $1$ бул $x$ минимум чекити, ал эми функциянын мааниси $f(1)$ суралып жатат."},{"id":"d","label":"$-1$","explain_ru":"Неверно: $-1$ это абсцисса точки максимума, а не значение минимума.","explain_ky":"Туура эмес: $-1$ бул минимумдун мааниси эмес, максимум чекитинин абсциссасы."}],"answer_index":0,"solution_ru":["$f''(x) = 3x^2 - 3 = 3(x - 1)(x + 1)$, нули $x = -1$ и $x = 1$.","Знаки $f''$: плюс на $(-\\infty, -1)$, минус на $(-1, 1)$, плюс на $(1, +\\infty)$.","Минимум в точке $x = 1$: $f(1) = 1 - 3 = -2$."],"solution_ky":["$f''(x) = 3x^2 - 3 = 3(x - 1)(x + 1)$, нөлдөрү $x = -1$ жана $x = 1$.","$f''$ белгилери: $(-\\infty, -1)$ аралыгында плюс, $(-1, 1)$ аралыгында минус, $(1, +\\infty)$ аралыгында плюс.","Минимум $x = 1$ чекитинде: $f(1) = 1 - 3 = -2$."],"terms":[{"en":"local minimum value","ru":"значение локального минимума","ky":"локалдык минимумдун мааниси"},{"en":"critical point","ru":"критическая точка","ky":"критикалык чекит"}],"skill":"extremum-value","est_seconds":75}'::JSONB),
  ('6ef1891e-b7e7-512d-8b04-484efb0a3ba3', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-derivative-007', 'm2-derivative', '2.4', 2, 'diagnostic', 'evo_authored', '{"stem_en":"A particle moves along a straight line. At time $t$ (in seconds), its position is $s(t) = t^2 + 3t$ meters. Find its instantaneous velocity at $t = 2$.","options":[{"id":"a","label":"$10$ m/s","explain_ru":"Неверно: $s(2) = 10$ м это положение в момент $t = 2$, а не скорость.","explain_ky":"Туура эмес: $s(2) = 10$ м бул ылдамдык эмес, $t = 2$ учурундагы абал."},{"id":"b","label":"$5$ m/s","explain_ru":"Неверно: это средняя скорость на отрезке $[0, 2]$: $\\frac{10}{2} = 5$. Мгновенная скорость равна производной.","explain_ky":"Туура эмес: бул $[0, 2]$ аралыгындагы орточо ылдамдык: $\\frac{10}{2} = 5$. Учурдагы ылдамдык туундуга барабар."},{"id":"c","label":"$4$ m/s","explain_ru":"Неверно: потеряна производная слагаемого $3t$, она равна $3$.","explain_ky":"Туура эмес: $3t$ кошулуучусунун туундусу жоголгон, ал $3$ болот."},{"id":"d","label":"$7$ m/s","explain_ru":"Верно: $v(t) = s''(t) = 2t + 3$, поэтому $v(2) = 7$ м/с.","explain_ky":"Туура: $v(t) = s''(t) = 2t + 3$, ошондуктан $v(2) = 7$ м/с."}],"answer_index":3,"solution_ru":["Мгновенная скорость: $v(t) = s''(t)$.","$s''(t) = 2t + 3$.","$v(2) = 4 + 3 = 7$ м/с."],"solution_ky":["Учурдагы ылдамдык: $v(t) = s''(t)$.","$s''(t) = 2t + 3$.","$v(2) = 4 + 3 = 7$ м/с."],"terms":[{"en":"instantaneous velocity","ru":"мгновенная скорость","ky":"учурдагы ылдамдык"},{"en":"rate of change","ru":"скорость изменения","ky":"өзгөрүү ылдамдыгы"}],"skill":"rate-of-change","est_seconds":75}'::JSONB),
  ('838cba89-a66e-5815-894c-4c2301de4ca7', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-derivative-008', 'm2-derivative', '2.4', 3, 'practice', 'evo_authored', '{"stem_en":"For which values of $a$ is the function $f(x) = x^3 + ax$ strictly increasing on $\\mathbb{R}$?","options":[{"id":"a","label":"$a > 0$","explain_ru":"Неверно: при $a = 0$ получаем $f(x) = x^3$, и она тоже строго возрастает на всей прямой. Производная $3x^2$ обращается в ноль только в одной точке, это не мешает росту.","explain_ky":"Туура эмес: $a = 0$ болгондо $f(x) = x^3$ чыгат, ал да бүт түз сызыкта катуу өсөт. $3x^2$ туундусу бир гана чекитте нөлгө айланат, бул өсүүгө тоскоол болбойт."},{"id":"b","label":"$a \\geq 0$","explain_ru":"Верно: $f''(x) = 3x^2 + a \\geq 0$ при всех $x$ ровно тогда, когда $a \\geq 0$. При $a = 0$ производная равна нулю только в точке $x = 0$.","explain_ky":"Туура: $f''(x) = 3x^2 + a \\geq 0$ шарты бардык $x$ үчүн так $a \\geq 0$ болгондо аткарылат. $a = 0$ болгондо туунду $x = 0$ чекитинде гана нөлгө барабар."},{"id":"c","label":"$a \\leq 0$","explain_ru":"Неверно: при $a < 0$ производная $3x^2 + a$ отрицательна около $x = 0$, и там функция убывает.","explain_ky":"Туура эмес: $a < 0$ болгондо $3x^2 + a$ туундусу $x = 0$ жанында терс, ал жерде функция кемийт."},{"id":"d","label":"$a \\geq -3$","explain_ru":"Неверно: условие проверили только в точке $x = 1$: $3 + a \\geq 0$. Оно нужно при всех $x$, и самая трудная точка $x = 0$.","explain_ky":"Туура эмес: шарт $x = 1$ чекитинде гана текшерилген: $3 + a \\geq 0$. Ал бардык $x$ үчүн керек, эң оор чекит $x = 0$."}],"answer_index":1,"solution_ru":["$f''(x) = 3x^2 + a$.","Функция строго возрастает на $\\mathbb{R}$, если $f''(x) \\geq 0$ при всех $x$ и ноль бывает только в отдельных точках.","Наименьшее значение $3x^2 + a$ равно $a$ (при $x = 0$). Условие: $a \\geq 0$."],"solution_ky":["$f''(x) = 3x^2 + a$.","Эгер бардык $x$ үчүн $f''(x) \\geq 0$ болсо жана нөл айрым чекиттерде гана болсо, функция $\\mathbb{R}$ боюнча катуу өсөт.","$3x^2 + a$ туюнтмасынын эң кичине мааниси $a$ ($x = 0$ болгондо). Шарт: $a \\geq 0$."],"terms":[{"en":"increasing function","ru":"возрастающая функция","ky":"өсүүчү функция"},{"en":"for all real x","ru":"при всех действительных x","ky":"бардык чыныгы x үчүн"}],"skill":"monotonic-parameter","est_seconds":105}'::JSONB),
  ('f1bb423e-c95f-514a-8dcf-9745d4e0b14b', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-derivative-009', 'm2-derivative', '2.4', 3, 'practice', 'evo_authored', '{"stem_en":"Among all tangent lines to the curve $y = x^3 - 3x^2$, find the equation of the tangent line with the smallest slope.","options":[{"id":"a","label":"$y = -4$","explain_ru":"Неверно: это горизонтальная касательная в точке минимума $(2, -4)$, её наклон $0$. Но наклон бывает и отрицательным, наименьший равен $-3$.","explain_ky":"Туура эмес: бул $(2, -4)$ минимум чекитиндеги горизонталдык жаныма, анын жантаюусу $0$. Бирок жантаюу терс да болот, эң кичинеси $-3$."},{"id":"b","label":"$y = -3x + 5$","explain_ru":"Неверно: ошибка в знаке у точки. Касательная проходит через $(1, -2)$: $y + 2 = -3(x - 1)$, то есть $y = -3x + 1$.","explain_ky":"Туура эмес: чекиттин белгисинде ката. Жаныма $(1, -2)$ аркылуу өтөт: $y + 2 = -3(x - 1)$, башкача айтканда $y = -3x + 1$."},{"id":"c","label":"$y = -3x + 1$","explain_ru":"Верно: наклон $y'' = 3x^2 - 6x = 3(x - 1)^2 - 3$ наименьший при $x = 1$ и равен $-3$. Точка касания $(1, -2)$, касательная $y = -3x + 1$.","explain_ky":"Туура: $y'' = 3x^2 - 6x = 3(x - 1)^2 - 3$ жантаюусу $x = 1$ болгондо эң кичине жана $-3$ барабар. Жануу чекити $(1, -2)$, жаныма $y = -3x + 1$."},{"id":"d","label":"$y = -3x$","explain_ru":"Неверно: наклон $-3$ верный, но прямая должна проходить через точку касания $(1, -2)$, а не через начало координат.","explain_ky":"Туура эмес: $-3$ жантаюусу туура, бирок түз сызык координаталар башталышы аркылуу эмес, $(1, -2)$ жануу чекити аркылуу өтүшү керек."}],"answer_index":2,"solution_ru":["Наклон касательной в точке $x$: $y'' = 3x^2 - 6x$.","$3x^2 - 6x = 3(x - 1)^2 - 3 \\geq -3$, равенство при $x = 1$.","Точка касания: $y(1) = 1 - 3 = -2$.","$y + 2 = -3(x - 1) \\Rightarrow y = -3x + 1$."],"solution_ky":["$x$ чекитиндеги жаныманын жантаюусу: $y'' = 3x^2 - 6x$.","$3x^2 - 6x = 3(x - 1)^2 - 3 \\geq -3$, барабардык $x = 1$ болгондо.","Жануу чекити: $y(1) = 1 - 3 = -2$.","$y + 2 = -3(x - 1) \\Rightarrow y = -3x + 1$."],"terms":[{"en":"smallest slope","ru":"наименьший угловой коэффициент","ky":"эң кичине бурчтук коэффициент"},{"en":"tangent line","ru":"касательная","ky":"жаныма"}],"skill":"tangent-min-slope","est_seconds":105}'::JSONB),
  ('de86a209-7e2e-592e-8789-c3673f4d9488', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-derivative-010', 'm2-derivative', '2.4', 3, 'mock', 'evo_authored', '{"stem_en":"The line $y = kx$ is tangent to the curve $y = \\ln x$. Find $k$.","options":[{"id":"a","label":"$e$","explain_ru":"Неверно: $e$ это абсцисса точки касания. Наклон в ней равен $\\frac{1}{e}$.","explain_ky":"Туура эмес: $e$ бул жануу чекитинин абсциссасы. Андагы жантаюу $\\frac{1}{e}$ болот."},{"id":"b","label":"$1$","explain_ru":"Неверно: это наклон касательной в точке $x = 1$. Но там касательная $y = x - 1$ не проходит через начало координат.","explain_ky":"Туура эмес: бул $x = 1$ чекитиндеги жаныманын жантаюусу. Бирок ал жердеги $y = x - 1$ жанымасы координаталар башталышы аркылуу өтпөйт."},{"id":"c","label":"$\\frac{1}{10}$","explain_ru":"Неверно: $\\ln$ спутали с десятичным логарифмом и из $\\ln t = 1$ получили $t = 10$. Для натурального логарифма $t = e$.","explain_ky":"Туура эмес: $\\ln$ ондук логарифм менен чаташтырылып, $\\ln t = 1$ теңдемесинен $t = 10$ алынган. Натуралдык логарифм үчүн $t = e$."},{"id":"d","label":"$\\frac{1}{e}$","explain_ru":"Верно: в точке касания $(t, \\ln t)$ наклон равен $\\frac{1}{t}$. Прямая проходит через начало координат: $\\ln t = \\frac{1}{t} \\cdot t = 1$, значит $t = e$ и $k = \\frac{1}{e}$.","explain_ky":"Туура: $(t, \\ln t)$ жануу чекитинде жантаюу $\\frac{1}{t}$ барабар. Түз сызык координаталар башталышы аркылуу өтөт: $\\ln t = \\frac{1}{t} \\cdot t = 1$, демек $t = e$ жана $k = \\frac{1}{e}$."}],"answer_index":3,"solution_ru":["Пусть точка касания $(t, \\ln t)$, $t > 0$. Так как $(\\ln x)'' = \\frac{1}{x}$, наклон $k = \\frac{1}{t}$.","Точка лежит на прямой $y = kx$: $\\ln t = \\frac{1}{t} \\cdot t = 1$.","$t = e$, поэтому $k = \\frac{1}{e}$."],"solution_ky":["Жануу чекити $(t, \\ln t)$, $t > 0$ болсун. $(\\ln x)'' = \\frac{1}{x}$ болгондуктан жантаюу $k = \\frac{1}{t}$.","Чекит $y = kx$ түз сызыгында жатат: $\\ln t = \\frac{1}{t} \\cdot t = 1$.","$t = e$, ошондуктан $k = \\frac{1}{e}$."],"terms":[{"en":"natural logarithm","ru":"натуральный логарифм","ky":"натуралдык логарифм"},{"en":"tangent line through the origin","ru":"касательная через начало координат","ky":"координаталар башталышы аркылуу өткөн жаныма"}],"skill":"tangent-through-point","est_seconds":105}'::JSONB),
  ('c8b50a67-f714-54ee-81eb-83ed492c5830', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-line-circle-001', 'm3-line-circle', '3.1', 1, 'lesson', 'evo_authored', '{"stem_en":"Find the center and the radius of the circle $x^2 + y^2 - 4x + 6y - 3 = 0$.","options":[{"id":"a","label":"center $(2, -3)$, radius $4$","explain_ru":"Верно: $(x - 2)^2 + (y + 3)^2 = 3 + 4 + 9 = 16$, центр $(2, -3)$, радиус $4$.","explain_ky":"Туура: $(x - 2)^2 + (y + 3)^2 = 3 + 4 + 9 = 16$, борбору $(2, -3)$, радиусу $4$."},{"id":"b","label":"center $(-2, 3)$, radius $4$","explain_ru":"Неверно: ошибка в знаках центра. В записи $(x - a)^2 + (y - b)^2$ центр $(a, b)$, а у нас $(x - 2)^2 + (y + 3)^2$, то есть центр $(2, -3)$.","explain_ky":"Туура эмес: борбордун белгилеринде ката. $(x - a)^2 + (y - b)^2$ жазуусунда борбор $(a, b)$, бизде $(x - 2)^2 + (y + 3)^2$, башкача айтканда борбор $(2, -3)$."},{"id":"c","label":"center $(2, -3)$, radius $16$","explain_ru":"Неверно: $16$ это $r^2$. Радиус равен $\\sqrt{16} = 4$.","explain_ky":"Туура эмес: $16$ бул $r^2$. Радиус $\\sqrt{16} = 4$."},{"id":"d","label":"center $(2, -3)$, radius $\\sqrt{3}$","explain_ru":"Неверно: при выделении квадратов к правой части нужно прибавить $4$ и $9$. Получится $16$, а не $3$.","explain_ky":"Туура эмес: квадраттарды бөлүп чыгарганда оң жагына $4$ жана $9$ кошуу керек. $3$ эмес, $16$ чыгат."}],"answer_index":0,"solution_ru":["Сгруппируем: $(x^2 - 4x) + (y^2 + 6y) = 3$.","Дополним до квадратов: $(x - 2)^2 - 4 + (y + 3)^2 - 9 = 3$.","$(x - 2)^2 + (y + 3)^2 = 16$: центр $(2, -3)$, $r = 4$."],"solution_ky":["Топтойбуз: $(x^2 - 4x) + (y^2 + 6y) = 3$.","Толук квадраттарга чейин толуктайбыз: $(x - 2)^2 - 4 + (y + 3)^2 - 9 = 3$.","$(x - 2)^2 + (y + 3)^2 = 16$: борбору $(2, -3)$, $r = 4$."],"terms":[{"en":"center","ru":"центр","ky":"борбор"},{"en":"radius","ru":"радиус","ky":"радиус"}],"skill":"circle-center-radius","est_seconds":45}'::JSONB),
  ('367567dd-e7f7-5213-8ee9-44badf3f1326', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-line-circle-002', 'm3-line-circle', '3.1', 1, 'lesson', 'evo_authored', '{"stem_en":"What is the slope of the line $2x - 3y + 6 = 0$?","options":[{"id":"a","label":"$-\\frac{2}{3}$","explain_ru":"Неверно: ошибка в знаке. Из $-3y = -2x - 6$ получаем $y = \\frac{2}{3}x + 2$, наклон положительный.","explain_ky":"Туура эмес: белгиде ката. $-3y = -2x - 6$ теңдемесинен $y = \\frac{2}{3}x + 2$ чыгат, жантаюу оң."},{"id":"b","label":"$\\frac{3}{2}$","explain_ru":"Неверно: дробь перевёрнута. Для $Ax + By + C = 0$ наклон равен $-\\frac{A}{B} = -\\frac{2}{-3} = \\frac{2}{3}$.","explain_ky":"Туура эмес: бөлчөк тескери алынган. $Ax + By + C = 0$ үчүн жантаюу $-\\frac{A}{B} = -\\frac{2}{-3} = \\frac{2}{3}$."},{"id":"c","label":"$\\frac{2}{3}$","explain_ru":"Верно: $y = \\frac{2}{3}x + 2$, угловой коэффициент $\\frac{2}{3}$.","explain_ky":"Туура: $y = \\frac{2}{3}x + 2$, бурчтук коэффициенти $\\frac{2}{3}$."},{"id":"d","label":"$2$","explain_ru":"Неверно: $2$ это ордината точки пересечения с осью $y$ (свободный член), а не наклон.","explain_ky":"Туура эмес: $2$ бул жантаюу эмес, $y$ огу менен кесилишүү чекитинин ординатасы (бош мүчө)."}],"answer_index":2,"solution_ru":["Выразим $y$: $3y = 2x + 6$.","$y = \\frac{2}{3}x + 2$.","Наклон $k = \\frac{2}{3}$."],"solution_ky":["$y$ аркылуу туюнтабыз: $3y = 2x + 6$.","$y = \\frac{2}{3}x + 2$.","Жантаюу $k = \\frac{2}{3}$."],"terms":[{"en":"slope","ru":"угловой коэффициент","ky":"бурчтук коэффициент"},{"en":"y-intercept","ru":"точка пересечения с осью y","ky":"y огу менен кесилишүү чекити"}],"skill":"line-slope","est_seconds":45}'::JSONB),
  ('3aeec143-32b0-55ec-8c40-7a7a6b75c27a', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-line-circle-003', 'm3-line-circle', '3.1', 1, 'lesson', 'evo_authored', '{"stem_en":"Find the distance from the point $(1, 2)$ to the line $3x + 4y - 1 = 0$.","options":[{"id":"a","label":"$10$","explain_ru":"Неверно: найден только числитель $|3 + 8 - 1| = 10$. Его нужно разделить на $\\sqrt{3^2 + 4^2} = 5$.","explain_ky":"Туура эмес: алым гана табылган: $|3 + 8 - 1| = 10$. Аны $\\sqrt{3^2 + 4^2} = 5$ санына бөлүү керек."},{"id":"b","label":"$2$","explain_ru":"Верно: $d = \\frac{|3 \\cdot 1 + 4 \\cdot 2 - 1|}{\\sqrt{3^2 + 4^2}} = \\frac{10}{5} = 2$.","explain_ky":"Туура: $d = \\frac{|3 \\cdot 1 + 4 \\cdot 2 - 1|}{\\sqrt{3^2 + 4^2}} = \\frac{10}{5} = 2$."},{"id":"c","label":"$\\frac{12}{5}$","explain_ru":"Неверно: свободный член взят со знаком плюс. В формулу подставляют $C = -1$: $|3 + 8 - 1| = 10$.","explain_ky":"Туура эмес: бош мүчө плюс белгиси менен алынган. Формулага $C = -1$ коюлат: $|3 + 8 - 1| = 10$."},{"id":"d","label":"$\\frac{10}{7}$","explain_ru":"Неверно: в знаменателе взяли $A + B = 7$. По формуле нужен $\\sqrt{A^2 + B^2} = 5$.","explain_ky":"Туура эмес: бөлүмгө $A + B = 7$ алынган. Формула боюнча $\\sqrt{A^2 + B^2} = 5$ керек."}],"answer_index":1,"solution_ru":["Формула: $d = \\frac{|Ax_0 + By_0 + C|}{\\sqrt{A^2 + B^2}}$.","$A = 3$, $B = 4$, $C = -1$, $(x_0, y_0) = (1, 2)$.","$d = \\frac{|3 + 8 - 1|}{5} = 2$."],"solution_ky":["Формула: $d = \\frac{|Ax_0 + By_0 + C|}{\\sqrt{A^2 + B^2}}$.","$A = 3$, $B = 4$, $C = -1$, $(x_0, y_0) = (1, 2)$.","$d = \\frac{|3 + 8 - 1|}{5} = 2$."],"terms":[{"en":"distance from a point to a line","ru":"расстояние от точки до прямой","ky":"чекиттен түз сызыкка чейинки аралык"}],"skill":"point-line-distance","est_seconds":45}'::JSONB),
  ('2174fddd-ed19-58d8-83fa-97c1788fdeba', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-line-circle-004', 'm3-line-circle', '3.1', 2, 'practice', 'evo_authored', '{"stem_en":"Find the equation of the line that passes through the point $(1, 2)$ and is perpendicular to the line $y = 2x + 1$.","options":[{"id":"a","label":"$2x - y = 0$","explain_ru":"Неверно: это прямая $y = 2x$, она параллельна данной. У перпендикулярной наклон $-\\frac{1}{2}$.","explain_ky":"Туура эмес: бул $y = 2x$ түз сызыгы, ал берилгенге параллель. Перпендикулярдын жантаюусу $-\\frac{1}{2}$."},{"id":"b","label":"$x - 2y + 3 = 0$","explain_ru":"Неверно: взят наклон $\\frac{1}{2}$ без минуса. У перпендикулярных прямых $k_1 k_2 = -1$.","explain_ky":"Туура эмес: $\\frac{1}{2}$ жантаюусу минуссуз алынган. Перпендикуляр түз сызыктар үчүн $k_1 k_2 = -1$."},{"id":"c","label":"$x + 2y - 3 = 0$","explain_ru":"Неверно: наклон верный, но ошибка в свободном члене. Подставьте точку: $1 + 2 \\cdot 2 - 3 = 2 \\ne 0$.","explain_ky":"Туура эмес: жантаюу туура, бирок бош мүчөдө ката. Чекитти коюп көрүңүз: $1 + 2 \\cdot 2 - 3 = 2 \\ne 0$."},{"id":"d","label":"$x + 2y - 5 = 0$","explain_ru":"Верно: наклон $-\\frac{1}{2}$, $y - 2 = -\\frac{1}{2}(x - 1)$, после умножения на $2$ получаем $x + 2y - 5 = 0$. Проверка: $1 + 4 - 5 = 0$.","explain_ky":"Туура: жантаюу $-\\frac{1}{2}$, $y - 2 = -\\frac{1}{2}(x - 1)$, $2$ге көбөйткөндөн кийин $x + 2y - 5 = 0$ чыгат. Текшерүү: $1 + 4 - 5 = 0$."}],"answer_index":3,"solution_ru":["Наклон данной прямой $2$, перпендикулярной $-\\frac{1}{2}$.","$y - 2 = -\\frac{1}{2}(x - 1)$.","Умножим на $2$: $2y - 4 = -x + 1$, то есть $x + 2y - 5 = 0$."],"solution_ky":["Берилген түз сызыктын жантаюусу $2$, перпендикулярдыкы $-\\frac{1}{2}$.","$y - 2 = -\\frac{1}{2}(x - 1)$.","$2$ге көбөйтөбүз: $2y - 4 = -x + 1$, башкача айтканда $x + 2y - 5 = 0$."],"terms":[{"en":"perpendicular","ru":"перпендикулярный","ky":"перпендикуляр"},{"en":"point-slope form","ru":"уравнение прямой через точку и наклон","ky":"чекит жана жантаюу аркылуу түз сызыктын теңдемеси"}],"skill":"perpendicular-line","est_seconds":75}'::JSONB),
  ('5c3511a4-3079-50d0-8d4f-541fa2a1ce94', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-line-circle-005', 'm3-line-circle', '3.1', 2, 'lesson', 'evo_authored', '{"stem_en":"The line $y = x + b$ is tangent to the circle $x^2 + y^2 = 2$. Find all possible values of $b$.","options":[{"id":"a","label":"$b = \\pm 2$","explain_ru":"Верно: прямая $x - y + b = 0$ касается окружности, когда расстояние от центра $(0, 0)$ равно радиусу: $\\frac{|b|}{\\sqrt{2}} = \\sqrt{2}$, то есть $|b| = 2$.","explain_ky":"Туура: $x - y + b = 0$ түз сызыгы борбордон $(0, 0)$ аралыгы радиуска барабар болгондо айланага жанат: $\\frac{|b|}{\\sqrt{2}} = \\sqrt{2}$, башкача айтканда $|b| = 2$."},{"id":"b","label":"$b = 2$","explain_ru":"Неверно: потерян второй случай. Из $|b| = 2$ следует $b = 2$ или $b = -2$: касательных две.","explain_ky":"Туура эмес: экинчи учур жоголгон. $|b| = 2$ шартынан $b = 2$ же $b = -2$ келип чыгат: жанымалар экөө."},{"id":"c","label":"$b = \\pm\\sqrt{2}$","explain_ru":"Неверно: забыт знаменатель $\\sqrt{1^2 + 1^2} = \\sqrt{2}$ в формуле расстояния.","explain_ky":"Туура эмес: аралык формуласындагы $\\sqrt{1^2 + 1^2} = \\sqrt{2}$ бөлүмү унутулган."},{"id":"d","label":"$b = \\pm 2\\sqrt{2}$","explain_ru":"Неверно: радиус приняли равным $2$. Но $r^2 = 2$, значит $r = \\sqrt{2}$.","explain_ky":"Туура эмес: радиус $2$ деп алынган. Бирок $r^2 = 2$, демек $r = \\sqrt{2}$."}],"answer_index":0,"solution_ru":["Центр $(0, 0)$, радиус $\\sqrt{2}$. Прямая: $x - y + b = 0$.","Касание: $d = r$, то есть $\\frac{|0 - 0 + b|}{\\sqrt{2}} = \\sqrt{2}$.","$|b| = 2$, $b = \\pm 2$."],"solution_ky":["Борбору $(0, 0)$, радиусу $\\sqrt{2}$. Түз сызык: $x - y + b = 0$.","Жануу: $d = r$, башкача айтканда $\\frac{|0 - 0 + b|}{\\sqrt{2}} = \\sqrt{2}$.","$|b| = 2$, $b = \\pm 2$."],"terms":[{"en":"tangent to a circle","ru":"касательная к окружности","ky":"айланага жаныма"}],"skill":"tangent-condition","est_seconds":75}'::JSONB),
  ('bd93fe28-2ea9-58de-8981-98d38b016440', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-line-circle-006', 'm3-line-circle', '3.1', 2, 'mock', 'evo_authored', '{"stem_en":"In the figure, the circle has center $C(3, 4)$ and passes through the origin $O$. Find the equation of the tangent line to the circle at $O$.","options":[{"id":"a","label":"$4x - 3y = 0$","explain_ru":"Неверно: это прямая $OC$, на ней лежит радиус. Касательная перпендикулярна радиусу.","explain_ky":"Туура эмес: бул $OC$ түз сызыгы, радиус ушул сызыкта жатат. Жаныма радиуска перпендикуляр."},{"id":"b","label":"$3x - 4y = 0$","explain_ru":"Неверно: наклон радиуса $\\frac{4}{3}$ перевернули, но не сменили знак. Нужен наклон $-\\frac{3}{4}$.","explain_ky":"Туура эмес: радиустун $\\frac{4}{3}$ жантаюусу тескери алынган, бирок белгиси өзгөртүлгөн жок. $-\\frac{3}{4}$ жантаюусу керек."},{"id":"c","label":"$3x + 4y = 0$","explain_ru":"Верно: наклон $OC$ равен $\\frac{4}{3}$, у касательной $-\\frac{3}{4}$. Прямая через $O$: $y = -\\frac{3}{4}x$, то есть $3x + 4y = 0$.","explain_ky":"Туура: $OC$ жантаюусу $\\frac{4}{3}$, жаныманыкы $-\\frac{3}{4}$. $O$ аркылуу өткөн түз сызык: $y = -\\frac{3}{4}x$, башкача айтканда $3x + 4y = 0$."},{"id":"d","label":"$4x + 3y = 0$","explain_ru":"Неверно: сменили знак, но не перевернули дробь, получился наклон $-\\frac{4}{3}$. Произведение наклонов должно быть $-1$.","explain_ky":"Туура эмес: белгиси өзгөртүлгөн, бирок бөлчөк тескери алынган жок, жантаюу $-\\frac{4}{3}$ болуп калды. Жантаюулардын көбөйтүндүсү $-1$ болушу керек."}],"answer_index":2,"solution_ru":["Касательная в точке окружности перпендикулярна радиусу, проведённому в эту точку.","Наклон $OC$: $\\frac{4 - 0}{3 - 0} = \\frac{4}{3}$, наклон касательной $-\\frac{3}{4}$.","Прямая через $O(0, 0)$: $y = -\\frac{3}{4}x$, то есть $3x + 4y = 0$."],"solution_ky":["Айлананын чекитиндеги жаныма ошол чекитке жүргүзүлгөн радиуска перпендикуляр.","$OC$ жантаюусу: $\\frac{4 - 0}{3 - 0} = \\frac{4}{3}$, жаныманын жантаюусу $-\\frac{3}{4}$.","$O(0, 0)$ аркылуу өткөн түз сызык: $y = -\\frac{3}{4}x$, башкача айтканда $3x + 4y = 0$."],"terms":[{"en":"the radius is perpendicular to the tangent","ru":"радиус перпендикулярен касательной","ky":"радиус жанымага перпендикуляр"}],"skill":"tangent-at-point","est_seconds":75,"figure_key":"item-circle-tangent"}'::JSONB),
  ('c7de7342-b5b4-5786-8305-b2ffab915be6', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-line-circle-007', 'm3-line-circle', '3.1', 2, 'diagnostic', 'evo_authored', '{"stem_en":"What is the positional relationship between the line $x - y + 1 = 0$ and the circle $(x - 1)^2 + y^2 = 1$?","options":[{"id":"a","label":"They intersect at two points.","explain_ru":"Неверно: расстояние $d = \\sqrt{2}$ сравнили с диаметром $2$. Сравнивать нужно с радиусом $1$: $\\sqrt{2} > 1$.","explain_ky":"Туура эмес: $d = \\sqrt{2}$ аралыгы $2$ диаметри менен салыштырылган. $1$ радиусу менен салыштыруу керек: $\\sqrt{2} > 1$."},{"id":"b","label":"They have no common points.","explain_ru":"Верно: расстояние от центра $(1, 0)$ до прямой $\\frac{|1 - 0 + 1|}{\\sqrt{2}} = \\sqrt{2}$ больше радиуса $1$.","explain_ky":"Туура: $(1, 0)$ борборунан түз сызыкка чейинки аралык $\\frac{|1 - 0 + 1|}{\\sqrt{2}} = \\sqrt{2}$, ал $1$ радиусунан чоң."},{"id":"c","label":"The line is tangent to the circle.","explain_ru":"Неверно: забыт корень в знаменателе: $\\frac{2}{2} = 1$. Правильно $\\frac{2}{\\sqrt{2}} = \\sqrt{2}$.","explain_ky":"Туура эмес: бөлүмдөгү тамыр унутулган: $\\frac{2}{2} = 1$. Туурасы $\\frac{2}{\\sqrt{2}} = \\sqrt{2}$."},{"id":"d","label":"The line passes through the center of the circle.","explain_ru":"Неверно: центр взяли как $(-1, 0)$. Из $(x - 1)^2$ следует центр $(1, 0)$, и он на прямой не лежит: $1 - 0 + 1 \\ne 0$.","explain_ky":"Туура эмес: борбор $(-1, 0)$ деп алынган. $(x - 1)^2$ жазуусунан борбор $(1, 0)$ экени чыгат, ал түз сызыкта жатпайт: $1 - 0 + 1 \\ne 0$."}],"answer_index":1,"solution_ru":["Центр $(1, 0)$, радиус $1$.","$d = \\frac{|1 - 0 + 1|}{\\sqrt{1 + 1}} = \\frac{2}{\\sqrt{2}} = \\sqrt{2}$.","$\\sqrt{2} > 1$, значит общих точек нет."],"solution_ky":["Борбору $(1, 0)$, радиусу $1$.","$d = \\frac{|1 - 0 + 1|}{\\sqrt{1 + 1}} = \\frac{2}{\\sqrt{2}} = \\sqrt{2}$.","$\\sqrt{2} > 1$, демек жалпы чекиттер жок."],"terms":[{"en":"no common points","ru":"нет общих точек","ky":"жалпы чекиттер жок"},{"en":"intersect","ru":"пересекаться","ky":"кесилишүү"}],"skill":"line-circle-position","est_seconds":75}'::JSONB),
  ('ffcd3c8f-9b0d-5a1e-84a4-391da6037a4b', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-line-circle-008', 'm3-line-circle', '3.1', 3, 'practice', 'evo_authored', '{"stem_en":"Find the length of the chord cut from the circle $x^2 + y^2 = 5$ by the line $x + y - 1 = 0$.","options":[{"id":"a","label":"$\\frac{3\\sqrt{2}}{2}$","explain_ru":"Неверно: это половина хорды. Перпендикуляр из центра делит хорду пополам, поэтому результат нужно удвоить.","explain_ky":"Туура эмес: бул хорданын жарымы. Борбордон түшүрүлгөн перпендикуляр хорданы тең экиге бөлөт, ошондуктан жыйынтыкты эки эсе көбөйтүү керек."},{"id":"b","label":"$4$","explain_ru":"Неверно: расстояние взяли равным $1$ и не разделили на $\\sqrt{2}$. Правильно $d = \\frac{1}{\\sqrt{2}}$.","explain_ky":"Туура эмес: аралык $1$ деп алынып, $\\sqrt{2}$ санына бөлүнгөн жок. Туурасы $d = \\frac{1}{\\sqrt{2}}$."},{"id":"c","label":"$2\\sqrt{5}$","explain_ru":"Неверно: $2\\sqrt{5}$ это диаметр. Хорда равна диаметру, только если прямая проходит через центр, а здесь это не так.","explain_ky":"Туура эмес: $2\\sqrt{5}$ бул диаметр. Түз сызык борбор аркылуу өтсө гана хорда диаметрге барабар, бул жерде андай эмес."},{"id":"d","label":"$3\\sqrt{2}$","explain_ru":"Верно: $d = \\frac{1}{\\sqrt{2}}$, половина хорды $\\sqrt{5 - \\frac{1}{2}} = \\frac{3}{\\sqrt{2}}$, хорда $\\frac{6}{\\sqrt{2}} = 3\\sqrt{2}$.","explain_ky":"Туура: $d = \\frac{1}{\\sqrt{2}}$, хорданын жарымы $\\sqrt{5 - \\frac{1}{2}} = \\frac{3}{\\sqrt{2}}$, хорда $\\frac{6}{\\sqrt{2}} = 3\\sqrt{2}$."}],"answer_index":3,"solution_ru":["Центр $(0, 0)$, $r = \\sqrt{5}$.","$d = \\frac{|0 + 0 - 1|}{\\sqrt{2}} = \\frac{1}{\\sqrt{2}}$.","Половина хорды: $\\sqrt{r^2 - d^2} = \\sqrt{5 - \\frac{1}{2}} = \\sqrt{\\frac{9}{2}} = \\frac{3}{\\sqrt{2}}$.","Хорда: $2 \\cdot \\frac{3}{\\sqrt{2}} = 3\\sqrt{2}$."],"solution_ky":["Борбору $(0, 0)$, $r = \\sqrt{5}$.","$d = \\frac{|0 + 0 - 1|}{\\sqrt{2}} = \\frac{1}{\\sqrt{2}}$.","Хорданын жарымы: $\\sqrt{r^2 - d^2} = \\sqrt{5 - \\frac{1}{2}} = \\sqrt{\\frac{9}{2}} = \\frac{3}{\\sqrt{2}}$.","Хорда: $2 \\cdot \\frac{3}{\\sqrt{2}} = 3\\sqrt{2}$."],"terms":[{"en":"chord","ru":"хорда","ky":"хорда"},{"en":"perpendicular from the center","ru":"перпендикуляр из центра","ky":"борбордон түшүрүлгөн перпендикуляр"}],"skill":"chord-length","est_seconds":105}'::JSONB),
  ('c3d037d7-abf5-5cb7-858d-354947e812e1', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-line-circle-009', 'm3-line-circle', '3.1', 3, 'mock', 'evo_authored', '{"stem_en":"A circle has its center on the $x$-axis and passes through the points $A(1, 3)$ and $B(5, 1)$. Find its equation.","options":[{"id":"a","label":"$(x - 2)^2 + y^2 = 10$","explain_ru":"Верно: центр $(a, 0)$ равноудалён от $A$ и $B$: $(1 - a)^2 + 9 = (5 - a)^2 + 1$, откуда $a = 2$ и $r^2 = 1 + 9 = 10$.","explain_ky":"Туура: $(a, 0)$ борбору $A$ жана $B$ чекиттеринен бирдей алыстыкта: $(1 - a)^2 + 9 = (5 - a)^2 + 1$, мындан $a = 2$ жана $r^2 = 1 + 9 = 10$."},{"id":"b","label":"$(x + 2)^2 + y^2 = 10$","explain_ru":"Неверно: центр $(2, 0)$ записан с неправильным знаком. Центру $(a, 0)$ соответствует $(x - a)^2$.","explain_ky":"Туура эмес: $(2, 0)$ борбору туура эмес белги менен жазылган. $(a, 0)$ борборуна $(x - a)^2$ туура келет."},{"id":"c","label":"$(x - 3)^2 + (y - 2)^2 = 5$","explain_ru":"Неверно: здесь $AB$ считают диаметром и берут центр в середине $(3, 2)$. Но центр должен лежать на оси $x$.","explain_ky":"Туура эмес: бул жерде $AB$ диаметр деп эсептелип, борбор анын ортосунда, $(3, 2)$ чекитинде алынган. Бирок борбор $x$ огунда жатышы керек."},{"id":"d","label":"$(x - 2)^2 + y^2 = 4$","explain_ru":"Неверно: при подсчёте $r^2$ забыли возвести $3$ в квадрат: $(1 - 2)^2 + 3^2 = 10$, а не $4$.","explain_ky":"Туура эмес: $r^2$ эсептегенде $3$ квадратка көтөрүлгөн жок: $(1 - 2)^2 + 3^2 = 10$, $4$ эмес."}],"answer_index":0,"solution_ru":["Пусть центр $C(a, 0)$. Тогда $|CA| = |CB|$.","$(1 - a)^2 + 3^2 = (5 - a)^2 + 1^2$.","$a^2 - 2a + 10 = a^2 - 10a + 26 \\Rightarrow 8a = 16 \\Rightarrow a = 2$.","$r^2 = (1 - 2)^2 + 3^2 = 10$. Проверка точкой $B$: $3^2 + 1^2 = 10$."],"solution_ky":["Борбор $C(a, 0)$ болсун. Анда $|CA| = |CB|$.","$(1 - a)^2 + 3^2 = (5 - a)^2 + 1^2$.","$a^2 - 2a + 10 = a^2 - 10a + 26 \\Rightarrow 8a = 16 \\Rightarrow a = 2$.","$r^2 = (1 - 2)^2 + 3^2 = 10$. $B$ чекити менен текшерүү: $3^2 + 1^2 = 10$."],"terms":[{"en":"equidistant","ru":"равноудалённый","ky":"бирдей алыстыкта"},{"en":"equation of a circle","ru":"уравнение окружности","ky":"айлананын теңдемеси"}],"skill":"circle-equation","est_seconds":105}'::JSONB),
  ('49a3957e-f98f-5b1e-800b-fdc2cde16704', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-line-circle-010', 'm3-line-circle', '3.1', 3, 'practice', 'evo_authored', '{"stem_en":"A point $P$ moves on the circle $x^2 + y^2 = 1$. Find the maximum distance from $P$ to the line $3x + 4y - 10 = 0$.","options":[{"id":"a","label":"$2$","explain_ru":"Неверно: $2$ это расстояние от центра до прямой. Самая дальняя точка окружности дальше ещё на радиус.","explain_ky":"Туура эмес: $2$ бул борбордон түз сызыкка чейинки аралык. Айлананын эң алыскы чекити андан дагы бир радиуска алыс."},{"id":"b","label":"$3$","explain_ru":"Верно: от центра до прямой $\\frac{|-10|}{5} = 2$. Самая дальняя точка окружности лежит на перпендикуляре из центра к прямой, по другую сторону от центра: $2 + 1 = 3$.","explain_ky":"Туура: борбордон түз сызыкка чейин $\\frac{|-10|}{5} = 2$. Айлананын эң алыскы чекити борбордон түз сызыкка түшүрүлгөн перпендикулярда, борбордун аркы тарабында жатат: $2 + 1 = 3$."},{"id":"c","label":"$1$","explain_ru":"Неверно: $2 - 1 = 1$ это наименьшее расстояние. Спрашивают наибольшее: $2 + 1$.","explain_ky":"Туура эмес: $2 - 1 = 1$ бул эң кичине аралык. Эң чоңу суралып жатат: $2 + 1$."},{"id":"d","label":"$\\frac{7}{5}$","explain_ru":"Неверно: подставили одну точку $P(1, 0)$: $\\frac{|3 - 10|}{5} = \\frac{7}{5}$. Это не наибольшее значение.","explain_ky":"Туура эмес: бир гана $P(1, 0)$ чекити коюлган: $\\frac{|3 - 10|}{5} = \\frac{7}{5}$. Бул эң чоң маани эмес."}],"answer_index":1,"solution_ru":["Расстояние от центра $(0, 0)$: $d = \\frac{|-10|}{\\sqrt{9 + 16}} = 2$.","$d > r = 1$, прямая не пересекает окружность.","Наибольшее расстояние $d + r = 3$, наименьшее $d - r = 1$."],"solution_ky":["$(0, 0)$ борборунан аралык: $d = \\frac{|-10|}{\\sqrt{9 + 16}} = 2$.","$d > r = 1$, түз сызык айлананы кеспейт.","Эң чоң аралык $d + r = 3$, эң кичинеси $d - r = 1$."],"terms":[{"en":"maximum distance","ru":"наибольшее расстояние","ky":"эң чоң аралык"}],"skill":"max-distance","est_seconds":105}'::JSONB);
INSERT INTO platform_private.learning_lessons (id, module_id, lesson_key, order_index, metadata, theory)
VALUES
  ('6a568c67-44e7-56dd-8ba5-c1b77305daba', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-m2-exp-log-l1', 1, '{"title_ru":"Показательная и логарифмическая функции","title_ky":"Көрсөткүчтүү жана логарифмдик функциялар","title_en":"Exponential and logarithmic functions","goal_ru":"Понять, что логарифм отвечает на вопрос «в какую степень», читать графики $a^x$ и $\\log_a x$ и решать задачи без калькулятора.","goal_ky":"Логарифм «кайсы даражага» деген суроого жооп берерин түшүнүү, $a^x$ жана $\\log_a x$ графиктерин окуу жана маселелерди калькуляторсуз чыгаруу.","topic_key":"m2-exp-log","kind":"lesson","est_minutes":15,"syllabus_point":"2.2"}'::JSONB, '[{"kind":"idea","ru":"Логарифм отвечает на один вопрос: в какую степень нужно возвести основание, чтобы получить число. $\\log_2 8 = 3$, потому что $2^3 = 8$. Показательная функция (exponential function) $y = a^x$ и логарифмическая функция (logarithmic function) $y = \\log_a x$ делают обратные действия. Поэтому это взаимно обратные функции (inverse functions).","ky":"Логарифм бир гана суроого жооп берет: санды алуу үчүн негизди кайсы даражага көтөрүү керек. $\\log_2 8 = 3$, анткени $2^3 = 8$. Көрсөткүчтүү функция (exponential function) $y = a^x$ жана логарифмдик функция (logarithmic function) $y = \\log_a x$ карама-каршы амалдарды аткарат. Ошондуктан алар өз ара тескери функциялар (inverse functions)."},{"kind":"formula","tex":["\\log_a b = c \\quad \\Leftrightarrow \\quad a^c = b","a > 0, \\quad a \\ne 1, \\quad b > 0"],"note_ru":"Основание положительное и не равно единице, число под логарифмом положительное. Отсюда область определения: $\\log_a x$ существует только при $x > 0$.","note_ky":"Негизи оң жана бирге барабар эмес, логарифмдин астындагы сан оң. Мындан аныкталуу областы чыгат: $\\log_a x$ бир гана $x > 0$ болгондо бар."},{"kind":"figure","figure_key":"exp-log-mirror","caption_ru":"Графики $y = 2^x$ и $y = \\log_2 x$ симметричны относительно прямой $y = x$: точка $(1, 2)$ переходит в $(2, 1)$, точка $(0, 1)$ в $(1, 0)$.","caption_ky":"$y = 2^x$ жана $y = \\log_2 x$ графиктери $y = x$ түз сызыгына карата симметриялуу: $(1, 2)$ чекити $(2, 1)$ чекитине, $(0, 1)$ чекити $(1, 0)$ чекитине өтөт."},{"kind":"table","caption_ru":"Свойства двух функций","caption_ky":"Эки функциянын касиеттери","header":[{"ru":"Свойство","ky":"Касиет"},{"tex":"y = a^x"},{"tex":"y = \\log_a x"}],"rows":[[{"ru":"Область определения","ky":"Аныкталуу областы"},{"tex":"x \\in \\mathbb{R}"},{"tex":"x > 0"}],[{"ru":"Множество значений","ky":"Маанилер областы"},{"tex":"y > 0"},{"tex":"y \\in \\mathbb{R}"}],[{"ru":"Опорная точка","ky":"Таяныч чекит"},{"tex":"(0, 1)"},{"tex":"(1, 0)"}],[{"ru":"Асимптота","ky":"Асимптота"},{"tex":"y = 0"},{"tex":"x = 0"}],[{"ru":"При $a > 1$","ky":"$a > 1$ болгондо"},{"ru":"возрастает","ky":"өсөт"},{"ru":"возрастает","ky":"өсөт"}],[{"ru":"При $0 < a < 1$","ky":"$0 < a < 1$ болгондо"},{"ru":"убывает","ky":"кемийт"},{"ru":"убывает","ky":"кемийт"}]]},{"kind":"figure","figure_key":"exp-base","caption_ru":"Основание решает, растёт функция или убывает. Графики $y = 2^x$ и $y = \\left(\\frac{1}{2}\\right)^x$ симметричны относительно оси $y$, и оба проходят через $(0, 1)$.","caption_ky":"Функция өсөбү же кемийби, аны негиз чечет. $y = 2^x$ жана $y = \\left(\\frac{1}{2}\\right)^x$ графиктери $y$ огуна карата симметриялуу жана экөө тең $(0, 1)$ аркылуу өтөт."},{"kind":"formula","tex":["\\log_a (MN) = \\log_a M + \\log_a N","\\log_a \\frac{M}{N} = \\log_a M - \\log_a N","\\log_a M^k = k \\log_a M","\\log_a b = \\frac{\\log_c b}{\\log_c a}"],"note_ru":"Первые три правила работают при одном основании и положительных $M$ и $N$. Последняя формула (change of base formula) переводит логарифм к удобному основанию.","note_ky":"Алгачкы үч эреже негизи бирдей жана $M$, $N$ оң болгондо иштейт. Акыркы формула (change of base formula) логарифмди ыңгайлуу негизге өткөрөт."},{"kind":"example","title_ru":"Разбор 1. Уравнение с логарифмами","title_ky":"1-талдоо. Логарифмдүү теңдеме","stem_en":"Solve the equation $\\log_3 (x + 1) + \\log_3 (x - 1) = 1$.","steps":[{"ru":"Область определения: $x + 1 > 0$ и $x - 1 > 0$, то есть $x > 1$.","ky":"Аныкталуу областы: $x + 1 > 0$ жана $x - 1 > 0$, башкача айтканда $x > 1$."},{"ru":"Сумма логарифмов равна логарифму произведения: $\\log_3 ((x + 1)(x - 1)) = 1$.","ky":"Логарифмдердин суммасы көбөйтүндүнүн логарифмине барабар: $\\log_3 ((x + 1)(x - 1)) = 1$."},{"ru":"По определению логарифма: $(x + 1)(x - 1) = 3^1$, то есть $x^2 - 1 = 3$ и $x = \\pm 2$.","ky":"Логарифмдин аныктамасы боюнча: $(x + 1)(x - 1) = 3^1$, башкача айтканда $x^2 - 1 = 3$ жана $x = \\pm 2$."},{"ru":"Сверяем с областью определения: $x = -2$ не подходит, остаётся $x = 2$.","ky":"Аныкталуу областы менен салыштырабыз: $x = -2$ туура келбейт, $x = 2$ калат."}],"answer_ru":"$x = 2$","answer_ky":"$x = 2$"},{"kind":"example","title_ru":"Разбор 2. Сравнение без калькулятора","title_ky":"2-талдоо. Калькуляторсуз салыштыруу","stem_en":"Arrange the numbers $2^{0.3}$, $0.3^2$ and $\\log_2 0.3$ in increasing order.","steps":[{"ru":"Сравниваем каждое число с $0$ и $1$.","ky":"Ар бир санды $0$ жана $1$ менен салыштырабыз."},{"ru":"$2^{0.3} > 2^0 = 1$, потому что $2^x$ возрастает.","ky":"$2^{0.3} > 2^0 = 1$, анткени $2^x$ өсөт."},{"ru":"$0.3^2 = 0.09$, это число между $0$ и $1$.","ky":"$0.3^2 = 0.09$, бул сан $0$ менен $1$ ортосунда."},{"ru":"$\\log_2 0.3 < \\log_2 1 = 0$, потому что $0.3 < 1$.","ky":"$\\log_2 0.3 < \\log_2 1 = 0$, анткени $0.3 < 1$."}],"answer_ru":"$\\log_2 0.3 < 0.3^2 < 2^{0.3}$","answer_ky":"$\\log_2 0.3 < 0.3^2 < 2^{0.3}$"},{"kind":"pitfalls","items":[{"ru":"$\\log_a (M + N) \\ne \\log_a M + \\log_a N$. Сумма логарифмов это логарифм произведения, а не суммы.","ky":"$\\log_a (M + N) \\ne \\log_a M + \\log_a N$. Логарифмдердин суммасы суммасынын эмес, көбөйтүндүнүн логарифми."},{"ru":"Забытая область определения даёт лишние корни. Сначала выпишите условие «аргумент больше нуля», потом решайте.","ky":"Унутулган аныкталуу областы ашыкча тамырларды берет. Адегенде «аргумент нөлдөн чоң» деген шартты жазыңыз, анан чыгарыңыз."},{"ru":"Если основание меньше единицы, при переходе от логарифмов к аргументам знак неравенства меняется на противоположный.","ky":"Негизи бирден кичине болсо, логарифмдерден аргументтерге өткөндө барабарсыздыктын белгиси карама-каршыга өзгөрөт."}]},{"kind":"tip","tip":"no_calculator","ru":"Без калькулятора помогают точные степени: $2^{10} = 1024$, $3^5 = 243$, $5^3 = 125$. Если число не точная степень, сравните логарифм с соседними целыми: $2 < \\log_2 5 < 3$, потому что $4 < 5 < 8$.","ky":"Калькуляторсуз так даражалар жардам берет: $2^{10} = 1024$, $3^5 = 243$, $5^3 = 125$. Эгер сан так даража болбосо, логарифмди коңшу бүтүн сандар менен салыштырыңыз: $2 < \\log_2 5 < 3$, анткени $4 < 5 < 8$."},{"kind":"terms","terms":[{"en":"exponential function","ru":"показательная функция","ky":"көрсөткүчтүү функция"},{"en":"logarithmic function","ru":"логарифмическая функция","ky":"логарифмдик функция"},{"en":"base","ru":"основание","ky":"негиз"},{"en":"exponent","ru":"показатель степени","ky":"даража көрсөткүчү"},{"en":"domain","ru":"область определения","ky":"аныкталуу областы"},{"en":"range","ru":"множество значений","ky":"маанилер областы"},{"en":"inverse function","ru":"обратная функция","ky":"тескери функция"},{"en":"asymptote","ru":"асимптота","ky":"асимптота"},{"en":"increasing","ru":"возрастающая","ky":"өсүүчү"},{"en":"decreasing","ru":"убывающая","ky":"кемүүчү"},{"en":"change of base formula","ru":"формула перехода к новому основанию","ky":"жаңы негизге өтүү формуласы"}]}]'::JSONB),
  ('22f0395c-b56d-5da0-8667-adec8f92a4e2', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-m2-exp-log-p1', 2, '{"title_ru":"Показательная и логарифмическая функции","title_ky":"Көрсөткүчтүү жана логарифмдик функциялар","title_en":"Exponential and logarithmic functions","goal_ru":"Задания по теме без таймера. После каждого ответа сразу виден разбор.","goal_ky":"Тема боюнча убакыт чектелбеген тапшырмалар. Ар бир жооптон кийин талдоо дароо көрүнөт.","topic_key":"m2-exp-log","kind":"practice","est_minutes":5,"syllabus_point":"2.2"}'::JSONB, '[]'::JSONB),
  ('f97f4659-8248-5af6-87b0-424a62d4ba74', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-m2-derivative-l1', 3, '{"title_ru":"Производная: касательная, рост и экстремумы","title_ky":"Туунду: жаныма, өсүү жана экстремумдар","title_en":"Derivatives: tangent lines, monotonicity and extrema","goal_ru":"Видеть в производной наклон касательной, писать уравнение касательной и по знаку производной находить, где функция растёт, убывает и имеет экстремум.","goal_ky":"Туундуну жаныманын жантаюусу катары көрүү, жаныманын теңдемесин жазуу жана туундунун белгиси боюнча функция кайда өсөрүн, кемирин жана экстремуму кайда экенин табуу.","topic_key":"m2-derivative","kind":"lesson","est_minutes":18,"syllabus_point":"2.4"}'::JSONB, '[{"kind":"idea","ru":"Возьмём на графике точку $P$ и ещё одну точку $Q$. Прямая $PQ$ называется секущей (secant line). Если двигать $Q$ к $P$, секущая поворачивается и приближается к касательной (tangent line). Наклон этой касательной и есть производная (derivative) $f''(x_0)$. Она показывает скорость изменения (rate of change) функции в точке.","ky":"Графиктен $P$ чекитин жана дагы бир $Q$ чекитин алалы. $PQ$ түз сызыгы кесүүчү (secant line) деп аталат. $Q$ чекитин $P$ чекитине жакындатсак, кесүүчү бурулуп, жанымага (tangent line) жакындайт. Ушул жаныманын жантаюусу туунду (derivative) $f''(x_0)$ болот. Ал функциянын чекиттеги өзгөрүү ылдамдыгын (rate of change) көрсөтөт."},{"kind":"figure","figure_key":"deriv-secant-tangent","caption_ru":"Парабола $y = x^2$ и точка $P(1, 1)$. Секущие через $Q_1(3, 9)$ и $Q_2(2, 4)$ имеют наклоны $4$ и $3$. Чем ближе $Q$ к $P$, тем ближе наклон к $2$: это наклон касательной $y = 2x - 1$.","caption_ky":"$y = x^2$ параболасы жана $P(1, 1)$ чекити. $Q_1(3, 9)$ жана $Q_2(2, 4)$ аркылуу өткөн кесүүчүлөрдүн жантаюулары $4$ жана $3$. $Q$ чекити $P$ чекитине канчалык жакын болсо, жантаюу ошончолук $2$ санына жакын: бул $y = 2x - 1$ жанымасынын жантаюусу."},{"kind":"formula","tex":["f''(x_0) = \\lim_{\\Delta x \\to 0} \\frac{f(x_0 + \\Delta x) - f(x_0)}{\\Delta x}"],"note_ru":"Дробь под знаком предела это наклон секущей. Её предел (limit) это наклон касательной.","note_ky":"Предел белгисинин астындагы бөлчөк кесүүчүнүн жантаюусу. Анын предели (limit) жаныманын жантаюусу."},{"kind":"table","caption_ru":"Производные, которые нужно знать наизусть","caption_ky":"Жатка билиш керек болгон туундулар","header":[{"ru":"Функция","ky":"Функция"},{"ru":"Производная","ky":"Туунду"}],"rows":[[{"tex":"c"},{"tex":"0"}],[{"tex":"x^n"},{"tex":"n x^{n-1}"}],[{"tex":"\\sin x"},{"tex":"\\cos x"}],[{"tex":"\\cos x"},{"tex":"-\\sin x"}],[{"tex":"a^x"},{"tex":"a^x \\ln a"}],[{"tex":"e^x"},{"tex":"e^x"}],[{"tex":"\\log_a x"},{"tex":"\\frac{1}{x \\ln a}"}],[{"tex":"\\ln x"},{"tex":"\\frac{1}{x}"}]]},{"kind":"formula","tex":["(u \\pm v)'' = u'' \\pm v''","(cu)'' = c u''","(uv)'' = u''v + uv''","\\left(\\frac{u}{v}\\right)'' = \\frac{u''v - uv''}{v^2}"],"note_ru":"Правила суммы, постоянного множителя, произведения и частного. Для многочленов хватает первых двух.","note_ky":"Сумманын, туруктуу көбөйтүүчүнүн, көбөйтүндүнүн жана тийиндинин эрежелери. Көп мүчөлөр үчүн алгачкы экөө жетиштүү."},{"kind":"formula","tex":["y - f(x_0) = f''(x_0)(x - x_0)"],"note_ru":"Уравнение касательной в точке $x_0$. Нужны две вещи: точка $(x_0, f(x_0))$ и наклон $f''(x_0)$.","note_ky":"$x_0$ чекитиндеги жаныманын теңдемеси. Эки нерсе керек: $(x_0, f(x_0))$ чекити жана $f''(x_0)$ жантаюусу."},{"kind":"example","title_ru":"Разбор 1. Касательная","title_ky":"1-талдоо. Жаныма","stem_en":"Find the equation of the tangent line to $y = x^2 - 3x$ at $x = 2$.","steps":[{"ru":"Точка касания: $y(2) = 4 - 6 = -2$, то есть $(2, -2)$.","ky":"Жануу чекити: $y(2) = 4 - 6 = -2$, башкача айтканда $(2, -2)$."},{"ru":"Наклон: $y'' = 2x - 3$, $y''(2) = 1$.","ky":"Жантаюу: $y'' = 2x - 3$, $y''(2) = 1$."},{"ru":"$y - (-2) = 1 \\cdot (x - 2)$, отсюда $y = x - 4$.","ky":"$y - (-2) = 1 \\cdot (x - 2)$, мындан $y = x - 4$."}],"answer_ru":"$y = x - 4$","answer_ky":"$y = x - 4$"},{"kind":"idea","ru":"Знак производной говорит о направлении. Если $f''(x) > 0$ на промежутке, функция там возрастает. Если $f''(x) < 0$, убывает. Точки, где производная равна нулю, называют критическими (critical point). Если в такой точке знак меняется с плюса на минус, это локальный максимум (local maximum). Если знак меняется с минуса на плюс, это локальный минимум (local minimum).","ky":"Туундунун белгиси багытты айтат. Эгер аралыкта $f''(x) > 0$ болсо, функция ал жерде өсөт. Эгер $f''(x) < 0$ болсо, кемийт. Туунду нөлгө барабар болгон чекиттер критикалык (critical point) деп аталат. Эгер мындай чекитте белги плюстан минуска өзгөрсө, бул локалдык максимум (local maximum). Белги минустан плюска өзгөрсө, бул локалдык минимум (local minimum)."},{"kind":"figure","figure_key":"deriv-sign-chart","caption_ru":"Функция $f(x) = x^3 - 12x$. Производная $f''(x) = 3x^2 - 12$ равна нулю при $x = \\pm 2$. Знаки $f''$: плюс, минус, плюс. Максимум $f(-2) = 16$, минимум $f(2) = -16$.","caption_ky":"$f(x) = x^3 - 12x$ функциясы. $f''(x) = 3x^2 - 12$ туундусу $x = \\pm 2$ болгондо нөлгө барабар. $f''$ белгилери: плюс, минус, плюс. Максимум $f(-2) = 16$, минимум $f(2) = -16$."},{"kind":"example","title_ru":"Разбор 2. Промежутки и экстремумы","title_ky":"2-талдоо. Аралыктар жана экстремумдар","stem_en":"Find the intervals of monotonicity and the local extrema of $f(x) = x^3 - 12x$.","steps":[{"ru":"$f''(x) = 3x^2 - 12 = 3(x - 2)(x + 2)$, нули $x = -2$ и $x = 2$.","ky":"$f''(x) = 3x^2 - 12 = 3(x - 2)(x + 2)$, нөлдөрү $x = -2$ жана $x = 2$."},{"ru":"Знак проверяем пробной точкой в каждом промежутке: $f''(-3) = 15 > 0$, $f''(0) = -12 < 0$, $f''(3) = 15 > 0$.","ky":"Белгини ар бир аралыкта сыноо чекити менен текшеребиз: $f''(-3) = 15 > 0$, $f''(0) = -12 < 0$, $f''(3) = 15 > 0$."},{"ru":"Функция возрастает на $(-\\infty, -2)$ и на $(2, +\\infty)$, убывает на $(-2, 2)$.","ky":"Функция $(-\\infty, -2)$ жана $(2, +\\infty)$ аралыктарында өсөт, $(-2, 2)$ аралыгында кемийт."},{"ru":"Локальный максимум $f(-2) = -8 + 24 = 16$, локальный минимум $f(2) = 8 - 24 = -16$.","ky":"Локалдык максимум $f(-2) = -8 + 24 = 16$, локалдык минимум $f(2) = 8 - 24 = -16$."}],"answer_ru":"максимум $16$ при $x = -2$, минимум $-16$ при $x = 2$","answer_ky":"$x = -2$ болгондо максимум $16$, $x = 2$ болгондо минимум $-16$"},{"kind":"pitfalls","items":[{"ru":"Из $f''(x_0) = 0$ ещё не следует экстремум. У $y = x^3$ производная в нуле равна нулю, но знак не меняется, и экстремума нет.","ky":"$f''(x_0) = 0$ болгону экстремум бар дегенди билдирбейт. $y = x^3$ функциясынын туундусу нөлдө нөлгө барабар, бирок белгиси өзгөрбөйт, экстремум жок."},{"ru":"Наклон касательной это $f''(x_0)$, а не $f(x_0)$. Значение функции нужно только для точки касания.","ky":"Жаныманын жантаюусу $f(x_0)$ эмес, $f''(x_0)$. Функциянын мааниси жануу чекити үчүн гана керек."},{"ru":"Наибольшее значение на отрезке ищут среди экстремумов и значений на концах. Конец отрезка может дать больше, чем локальный максимум.","ky":"Кесиндидеги эң чоң маани экстремумдардын жана учтардагы маанилердин арасынан изделет. Кесиндинин учу локалдык максимумдан чоң маани бериши мүмкүн."}]},{"kind":"tip","tip":"no_calculator","ru":"Знак производной удобно проверять пробной точкой. Выберите в каждом промежутке простое число ($0$, $\\pm 1$, $\\pm 3$) и подставьте его в $f''(x)$. Вычисления занимают одну строку.","ky":"Туундунун белгисин сыноо чекити менен текшерүү ыңгайлуу. Ар бир аралыктан жөнөкөй санды ($0$, $\\pm 1$, $\\pm 3$) тандап, $f''(x)$ туюнтмасына коюңуз. Эсептөө бир сапты гана алат."},{"kind":"terms","terms":[{"en":"derivative","ru":"производная","ky":"туунду"},{"en":"tangent line","ru":"касательная","ky":"жаныма"},{"en":"secant line","ru":"секущая","ky":"кесүүчү"},{"en":"slope","ru":"угловой коэффициент","ky":"бурчтук коэффициент"},{"en":"limit","ru":"предел","ky":"предел"},{"en":"increasing","ru":"возрастающая","ky":"өсүүчү"},{"en":"decreasing","ru":"убывающая","ky":"кемүүчү"},{"en":"local maximum","ru":"локальный максимум","ky":"локалдык максимум"},{"en":"local minimum","ru":"локальный минимум","ky":"локалдык минимум"},{"en":"critical point","ru":"критическая точка","ky":"критикалык чекит"},{"en":"rate of change","ru":"скорость изменения","ky":"өзгөрүү ылдамдыгы"}]}]'::JSONB),
  ('6a642eaf-446e-551e-8193-8ce8695fd52e', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-m2-derivative-p1', 4, '{"title_ru":"Производная: касательная, рост и экстремумы","title_ky":"Туунду: жаныма, өсүү жана экстремумдар","title_en":"Derivatives: tangent lines, monotonicity and extrema","goal_ru":"Задания по теме без таймера. После каждого ответа сразу виден разбор.","goal_ky":"Тема боюнча убакыт чектелбеген тапшырмалар. Ар бир жооптон кийин талдоо дароо көрүнөт.","topic_key":"m2-derivative","kind":"practice","est_minutes":5,"syllabus_point":"2.4"}'::JSONB, '[]'::JSONB),
  ('7f014b02-b63a-5322-8c71-d1e6ab8955db', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-m3-line-circle-l1', 5, '{"title_ru":"Прямая и окружность: всё решает расстояние","title_ky":"Түз сызык жана айлана: баарын аралык чечет","title_en":"Lines and circles: distance decides","goal_ru":"Находить наклон прямой и уравнение перпендикуляра, приводить уравнение окружности к виду с центром и радиусом, по расстоянию от центра до прямой решать задачи о касании и хордах.","goal_ky":"Түз сызыктын жантаюусун жана перпендикулярдын теңдемесин табуу, айлананын теңдемесин борбору жана радиусу көрүнгөн түргө келтирүү, борбордон түз сызыкка чейинки аралык боюнча жануу жана хорда маселелерин чыгаруу.","topic_key":"m3-line-circle","kind":"lesson","est_minutes":18,"syllabus_point":"3.1"}'::JSONB, '[{"kind":"idea","ru":"Наклон прямой (slope) показывает, на сколько меняется $y$, когда $x$ увеличивается на $1$. Через две точки: $k = \\frac{y_2 - y_1}{x_2 - x_1}$. У параллельных прямых наклоны равны, у перпендикулярных произведение наклонов равно $-1$.","ky":"Түз сызыктын жантаюусу (slope) $x$ бирге чоңойгондо $y$ канчага өзгөрөрүн көрсөтөт. Эки чекит аркылуу: $k = \\frac{y_2 - y_1}{x_2 - x_1}$. Параллель түз сызыктардын жантаюулары барабар, перпендикуляр түз сызыктардын жантаюуларынын көбөйтүндүсү $-1$."},{"kind":"formula","tex":["y - y_0 = k(x - x_0)","Ax + By + C = 0, \\quad k = -\\frac{A}{B}","\\parallel: \\quad k_1 = k_2","\\perp: \\quad k_1 k_2 = -1"],"note_ru":"Первая формула: прямая через точку $(x_0, y_0)$ с наклоном $k$. Вторая: общий вид прямой. У вертикальной прямой $x = c$ наклона нет.","note_ky":"Биринчи формула: $(x_0, y_0)$ чекити аркылуу өткөн, жантаюусу $k$ болгон түз сызык. Экинчиси: түз сызыктын жалпы түрү. Вертикалдык $x = c$ түз сызыгынын жантаюусу жок."},{"kind":"idea","ru":"Окружность (circle) с центром $(a, b)$ и радиусом $r$ это все точки на расстоянии $r$ от центра. Если уравнение дано в раскрытом виде, выделите полные квадраты, и центр с радиусом станут видны.","ky":"Борбору $(a, b)$, радиусу $r$ болгон айлана (circle) бул борбордон $r$ аралыкта жаткан бардык чекиттер. Эгер теңдеме ачылган түрдө берилсе, толук квадраттарды бөлүп чыгарыңыз, ошондо борбор менен радиус көрүнөт."},{"kind":"formula","tex":["(x - a)^2 + (y - b)^2 = r^2","d = \\frac{|Ax_0 + By_0 + C|}{\\sqrt{A^2 + B^2}}"],"note_ru":"Вторая формула даёт расстояние от точки $(x_0, y_0)$ до прямой $Ax + By + C = 0$. Это главный инструмент урока.","note_ky":"Экинчи формула $(x_0, y_0)$ чекитинен $Ax + By + C = 0$ түз сызыгына чейинки аралыкты берет. Бул сабактын негизги куралы."},{"kind":"figure","figure_key":"circle-line-positions","caption_ru":"Сравните расстояние $d$ от центра до прямой с радиусом $r$. Если $d > r$, общих точек нет. Если $d = r$, прямая касается окружности в одной точке. Если $d < r$, точек пересечения две.","caption_ky":"Борбордон түз сызыкка чейинки $d$ аралыгын $r$ радиусу менен салыштырыңыз. Эгер $d > r$ болсо, жалпы чекит жок. Эгер $d = r$ болсо, түз сызык айланага бир чекитте жанат. Эгер $d < r$ болсо, кесилишүү чекиттери экөө."},{"kind":"example","title_ru":"Разбор 1. Центр и радиус","title_ky":"1-талдоо. Борбор жана радиус","stem_en":"Find the center and the radius of the circle $x^2 + y^2 + 2x - 4y - 4 = 0$.","steps":[{"ru":"Сгруппируем: $(x^2 + 2x) + (y^2 - 4y) = 4$.","ky":"Топтойбуз: $(x^2 + 2x) + (y^2 - 4y) = 4$."},{"ru":"Выделим квадраты: $(x + 1)^2 - 1 + (y - 2)^2 - 4 = 4$.","ky":"Квадраттарды бөлүп чыгарабыз: $(x + 1)^2 - 1 + (y - 2)^2 - 4 = 4$."},{"ru":"$(x + 1)^2 + (y - 2)^2 = 9$.","ky":"$(x + 1)^2 + (y - 2)^2 = 9$."}],"answer_ru":"центр $(-1, 2)$, радиус $3$","answer_ky":"борбору $(-1, 2)$, радиусу $3$"},{"kind":"figure","figure_key":"circle-chord","caption_ru":"Перпендикуляр из центра делит хорду пополам. Радиус, расстояние $d$ и половина хорды образуют прямоугольный треугольник.","caption_ky":"Борбордон түшүрүлгөн перпендикуляр хорданы тең экиге бөлөт. Радиус, $d$ аралыгы жана хорданын жарымы тик бурчтуу үч бурчтукту түзөт."},{"kind":"formula","tex":["|AB| = 2\\sqrt{r^2 - d^2}"],"note_ru":"Формула следует прямо из теоремы Пифагора для этого треугольника.","note_ky":"Формула ушул үч бурчтук үчүн Пифагор теоремасынан түздөн-түз келип чыгат."},{"kind":"example","title_ru":"Разбор 2. Длина хорды","title_ky":"2-талдоо. Хорданын узундугу","stem_en":"The line $4x - 3y + 5 = 0$ meets the circle $(x + 1)^2 + (y - 2)^2 = 9$ at points $A$ and $B$. Find $|AB|$.","steps":[{"ru":"Центр $(-1, 2)$, $r = 3$.","ky":"Борбору $(-1, 2)$, $r = 3$."},{"ru":"$d = \\frac{|4 \\cdot (-1) - 3 \\cdot 2 + 5|}{\\sqrt{16 + 9}} = \\frac{5}{5} = 1$.","ky":"$d = \\frac{|4 \\cdot (-1) - 3 \\cdot 2 + 5|}{\\sqrt{16 + 9}} = \\frac{5}{5} = 1$."},{"ru":"$d < r$, прямая пересекает окружность. Половина хорды: $\\sqrt{r^2 - d^2} = \\sqrt{9 - 1} = 2\\sqrt{2}$.","ky":"$d < r$, түз сызык айлананы кесет. Хорданын жарымы: $\\sqrt{r^2 - d^2} = \\sqrt{9 - 1} = 2\\sqrt{2}$."},{"ru":"$|AB| = 2 \\cdot 2\\sqrt{2} = 4\\sqrt{2}$.","ky":"$|AB| = 2 \\cdot 2\\sqrt{2} = 4\\sqrt{2}$."}],"answer_ru":"$|AB| = 4\\sqrt{2}$","answer_ky":"$|AB| = 4\\sqrt{2}$"},{"kind":"pitfalls","items":[{"ru":"Координаты центра берут с противоположными знаками: запись $(x + 1)^2$ означает $a = -1$.","ky":"Борбордун координаталары карама-каршы белгилер менен алынат: $(x + 1)^2$ жазуусу $a = -1$ дегенди билдирет."},{"ru":"Справа в уравнении окружности стоит $r^2$, а не $r$. Не забудьте извлечь корень.","ky":"Айлананын теңдемесинин оң жагында $r$ эмес, $r^2$ турат. Тамыр чыгарууну унутпаңыз."},{"ru":"Перед формулой расстояния приведите прямую к виду $Ax + By + C = 0$ и подставляйте $C$ с его знаком. В знаменателе стоит $\\sqrt{A^2 + B^2}$, а не $A + B$.","ky":"Аралык формуласынын алдында түз сызыкты $Ax + By + C = 0$ түрүнө келтириңиз жана $C$ санын өз белгиси менен коюңуз. Бөлүмдө $A + B$ эмес, $\\sqrt{A^2 + B^2}$ турат."},{"ru":"Наклон перпендикуляра равен $-\\frac{1}{k}$: дробь переворачивают и меняют знак.","ky":"Перпендикулярдын жантаюусу $-\\frac{1}{k}$ барабар: бөлчөк тескери алынат жана белгиси өзгөрөт."}]},{"kind":"tip","tip":"no_calculator","ru":"Без калькулятора помогают пифагоровы тройки $3, 4, 5$ и $5, 12, 13$: знаменатели $\\sqrt{3^2 + 4^2} = 5$ и $\\sqrt{5^2 + 12^2} = 13$ получаются сразу. Оставляйте ответ с корнем: $3\\sqrt{2}$ точнее и быстрее, чем $4.24$.","ky":"Калькуляторсуз Пифагор үчтүктөрү жардам берет: $3, 4, 5$ жана $5, 12, 13$. $\\sqrt{3^2 + 4^2} = 5$ жана $\\sqrt{5^2 + 12^2} = 13$ бөлүмдөрү дароо чыгат. Жоопту тамыр менен калтырыңыз: $3\\sqrt{2}$ деп жазуу $4.24$ деп жазуудан так жана тез."},{"kind":"terms","terms":[{"en":"slope","ru":"угловой коэффициент","ky":"бурчтук коэффициент"},{"en":"parallel","ru":"параллельный","ky":"параллель"},{"en":"perpendicular","ru":"перпендикулярный","ky":"перпендикуляр"},{"en":"circle","ru":"окружность","ky":"айлана"},{"en":"center","ru":"центр","ky":"борбор"},{"en":"radius","ru":"радиус","ky":"радиус"},{"en":"chord","ru":"хорда","ky":"хорда"},{"en":"tangent line","ru":"касательная","ky":"жаныма"},{"en":"distance from a point to a line","ru":"расстояние от точки до прямой","ky":"чекиттен түз сызыкка чейинки аралык"},{"en":"intersect","ru":"пересекаться","ky":"кесилишүү"}]}]'::JSONB),
  ('43386f2c-1fae-57eb-8bb2-5f435235e9e3', 'a7bd0cdc-929a-50b1-8cdc-ed3374d8c730', 'csca-math-m3-line-circle-p1', 6, '{"title_ru":"Прямая и окружность: всё решает расстояние","title_ky":"Түз сызык жана айлана: баарын аралык чечет","title_en":"Lines and circles: distance decides","goal_ru":"Задания по теме без таймера. После каждого ответа сразу виден разбор.","goal_ky":"Тема боюнча убакыт чектелбеген тапшырмалар. Ар бир жооптон кийин талдоо дароо көрүнөт.","topic_key":"m3-line-circle","kind":"practice","est_minutes":5,"syllabus_point":"3.1"}'::JSONB, '[]'::JSONB);
INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
