', '0 0 360 348', 'Окружность с центром C(3, 4), проходящая через начало координат O. Проведён радиус OC и красная касательная к окружности в точке O. Радиус и касательная перпендикулярны.', 'Борбору C(3, 4) болгон жана координаталар башталышы O аркылуу өткөн айлана. OC радиусу жана O чекитиндеги кызыл жаныма жүргүзүлгөн. Радиус менен жаныманын ортосундагы бурч тик.', 'Circle with center C(3, 4) passing through the origin O; the radius OC and the red tangent line at O, which meet at a right angle.', '6211049c50d3976b0cc679866e422be3cc484550bf2e11c323e7a9be43d6f30e');






DO $p286$
DECLARE
  seeded_module_id UUID;
  n INTEGER;
BEGIN
  SELECT module.id INTO seeded_module_id FROM platform_private.learning_modules module
    WHERE module.module_key = 'csca-math' AND module.version = '1.0.0'
      AND module.track = 'csca-math';
  IF seeded_module_id IS NULL THEN
    RAISE EXCEPTION 'P286 seed assertion failed: module row is missing';
  END IF;
  SELECT count(*) INTO n FROM platform_private.learning_topics WHERE module_id = seeded_module_id;
  IF n <> 28 THEN RAISE EXCEPTION 'P286 seed assertion failed: expected 28 topics, found %', n; END IF;
  SELECT count(*) INTO n FROM platform_private.learning_figures WHERE module_id = seeded_module_id;
  IF n <> 9 THEN RAISE EXCEPTION 'P286 seed assertion failed: expected 9 figures, found %', n; END IF;
  SELECT count(*) INTO n FROM platform_private.learning_items
    WHERE module_id = seeded_module_id AND provenance = 'evo_authored';
  IF n <> 30 THEN RAISE EXCEPTION 'P286 seed assertion failed: expected 30 EVO items, found %', n; END IF;
  SELECT count(*) INTO n FROM platform_private.learning_lessons WHERE module_id = seeded_module_id;
  IF n <> 6 THEN RAISE EXCEPTION 'P286 seed assertion failed: expected 6 lessons, found %', n; END IF;
  SELECT count(*) INTO n FROM platform_private.learning_exercises exercise
    JOIN platform_private.learning_lessons lesson ON lesson.id = exercise.lesson_id
    WHERE lesson.module_id = seeded_module_id AND exercise.exercise_type = 'item';
  IF n <> 21 THEN RAISE EXCEPTION 'P286 seed assertion failed: expected 21 item exercises, found %', n; END IF;
  SELECT count(*) INTO n FROM platform_private.learning_test_forms WHERE module_id = seeded_module_id;
  IF n <> 2 THEN RAISE EXCEPTION 'P286 seed assertion failed: expected 2 forms, found %', n; END IF;
  SELECT count(DISTINCT session_key) INTO n FROM platform_private.csca_exam_sessions;
  IF n < 6 THEN RAISE EXCEPTION 'P286 seed assertion failed: expected 6 exam sessions, found %', n; END IF;
  -- Pools stay disjoint: every item is used once (lesson, practice or one form).
  SELECT count(*) INTO n FROM platform_private.learning_items item
    WHERE item.module_id = seeded_module_id
      AND (SELECT count(*) FROM platform_private.learning_exercises exercise
          JOIN platform_private.learning_lessons lesson ON lesson.id = exercise.lesson_id
          WHERE lesson.module_id = seeded_module_id AND exercise.exercise_key = item.item_key)
        + (SELECT count(*) FROM platform_private.learning_test_forms form
          WHERE form.module_id = seeded_module_id AND form.item_keys ? item.item_key) <> 1;
  IF n <> 0 THEN RAISE EXCEPTION 'P286 seed assertion failed: % items are not used exactly once', n; END IF;
END $p286$;

SELECT 'P286_CSCA_MATH_CONTENT_SEED_ASSERTED' AS p286_marker;

NOTIFY pgrst, 'reload schema';

COMMIT;
